insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0001','概念データモデル','概念データモデルの説明として、最も適切なものはどれか。','DM-A-17-02-01','ipa_past','出典：令和7年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問2','[{"id": 1, "body": "階層モデル、ネットワークモデル、関係モデルがある。"}, {"id": 2, "body": "業務プロセスを抽象化して表現したものである。"}, {"id": 3, "body": "集中型DBMSを導入するか、分散型DBMSを導入するかによって内容が変わる。"}, {"id": 4, "body": "対象世界の情報構造を抽象化して表現したものである。"}]'::jsonb,4,'概念データモデルは対象となる業務世界の情報構造を抽象化して表す。業務手順を表すものでも、特定DBMSの配置方式に依存するものでもない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0002','UMLの多重度','UMLを用いて表した商品と倉庫のデータモデルに関する記述のうち、適切なものはどれか。ここで、商品の倉庫間の移動はないものとする。','DM-A-17-02-02','ipa_past','出典：令和7年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問3','[{"id": 1, "body": "1種類の商品を二つの倉庫に初めて入庫すると、“在庫商品”データが2件追加される。"}, {"id": 2, "body": "2種類の商品を一つの倉庫に入庫すると、“入庫”データが1件追加される。"}, {"id": 3, "body": "格納先となる倉庫が確定していない在庫商品が存在する。"}, {"id": 4, "body": "出庫の実績がない在庫商品は存在しない。"}]'::jsonb,1,'在庫商品は一つの商品と一つの倉庫に関連する。同じ商品でも倉庫が二つなら在庫商品の組合せは二つになる。出庫側は0件も許されるため、出庫実績がない在庫商品も存在できる。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0003','モデルと具体例の整合性','データモデルを解釈してオブジェクト図を作成した。解釈の誤りを適切に指摘した記述はどれか。ここで、モデルの表記にはUMLを用い、オブジェクト図の一部の属性の表示は省略した。','DM-A-17-02-02','ipa_past','出典：令和7年度 秋期 システム監査技術者試験 午前Ⅱ 問21','[{"id": 1, "body": "“123456：注文”が複数の商品にリンクしているのは、誤りである。"}, {"id": 2, "body": "“2ドア冷蔵庫：商品”が複数の注文にリンクしているのは、誤りである。"}, {"id": 3, "body": "“A商店：顧客”が複数の注文にリンクしているのは、誤りである。"}, {"id": 4, "body": "“ドラム式洗濯機：商品”がどの注文にもリンクしていないのは、誤りである。"}]'::jsonb,1,'図のモデルでは各注文に対応する商品は一つである。注文123456から二つの商品へリンクしている点がモデルと矛盾する。顧客や商品から複数の注文へ関連すること、未注文の商品が存在することはモデルと矛盾しない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0004','学習と推論','クラウドで学習し、エッジデバイスで推論する機械学習ベースのエッジAIにおいて、エッジデバイスで行われる推論処理として、適切なものはどれか。','DM-A-10-02-03','ipa_past','出典：令和7年度 春期 高度試験共通 午前Ⅰ 問27／出典：令和7年度 春期 応用情報技術者試験 午前 問71','[{"id": 1, "body": "一定の環境の中で試行錯誤を行い、行動に報酬を与えることで学習するプロセス"}, {"id": 2, "body": "学習したモデルに従い、実際にデータの識別などを行うプロセス"}, {"id": 3, "body": "識別などを行うためのモデルを、正解のラベルを付けたデータによって作成するプロセス"}, {"id": 4, "body": "識別などを行うためのモデルを、正解のラベルを付けないデータによって作成するプロセス"}]'::jsonb,2,'推論は学習済みのモデルを用いて新しい入力に対する識別や予測を行う処理である。ほかの選択肢は学習の方法を説明している。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0005','画像認識AIの活用','スマートファクトリーで使用されるAIを用いたマシンビジョンの目的として、適切なものはどれか。','DM-A-10-02-02','ipa_past','出典：令和7年度 春期 高度試験共通 午前Ⅰ 問28／出典：令和7年度 春期 応用情報技術者試験 午前 問72','[{"id": 1, "body": "クラウドに蓄積した入出荷データを用いてAIが需要を予測し、生産数を最適化する。"}, {"id": 2, "body": "作業者が装着したVRゴーグルにAIが作業状況に応じたガイドを表示することによって、作業効率を向上させる。"}, {"id": 3, "body": "設計変更内容をAIによって整理し、製造現場に正確に伝える。"}, {"id": 4, "body": "人間の目視検査をAIが代替し、検査効率を向上させる。"}]'::jsonb,4,'マシンビジョンは画像から対象の状態などを認識する用途で使われる。選択肢では、製品の外観などを対象にした目視検査の代替が対応する。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0006','生成AIと著作権','著作権法及び関連法令によれば、生成AIを利用して画像を生成する行為又はその生成物の利用が著作権侵害にあたるか否かに関して、適切な記述はどれか。','DM-A-28-01-05','ipa_past','出典：令和7年度 春期 高度試験共通 午前Ⅰ 問30／出典：令和7年度 春期 応用情報技術者試験 午前 問78','[{"id": 1, "body": "AIが既存の著作権で保護されている画像をデータセットとして学習している場合は、そのAIを利用して画像を生成すると、いかなる場合も著作権侵害になる。"}, {"id": 2, "body": "AIを利用して生成した画像が著作権で保護された既存の画像と類似しており、それを公開した場合、著作権侵害となる可能性がある。"}, {"id": 3, "body": "AIを利用して生成した画像は、AIが自動的に創作したものであるため、いかなる状況でも著作権の対象外となり、著作権侵害の懸念は生じない。"}, {"id": 4, "body": "AIを利用して生成した画像は、生成した本人の私的使用に限って、利用が認められており、商業利用を行った場合は、いかなる場合も著作権侵害となる。"}]'::jsonb,2,'公式正答はイ。既存著作物との関係によって生成物の公開が侵害となる可能性はある。ほかの選択肢の「いかなる場合も」「いかなる状況でも」という一律の説明は適切ではない。個別の権利判断や現在の法令解釈を保証する解説ではなく、原試験の選択肢を理解するための説明。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0007','セキュリティの基本特性','JIS Q 27000:2019（情報セキュリティマネジメントシステム－用語）における真正性及び信頼性に対する定義a～dの組合せのうち、適切なものはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0008','製造時間の制約と利益','表のような製品A、Bを製造、販売する場合、考えられる利益は最大で何円になるか。ここで、機械の年間使用可能時間は延べ15,000時間とし、年間の固定費は製品A、Bに関係なく15,000,000円とする。','DM-A-09-03-02','ipa_past','出典：令和7年度 秋期 高度試験共通 午前Ⅰ 問29／出典：令和7年度 秋期 応用情報技術者試験 午前 問77','[{"id": 1, "body": "3,750,000"}, {"id": 2, "body": "7,500,000"}, {"id": 3, "body": "16,250,000"}, {"id": 4, "body": "18,750,000"}]'::jsonb,2,'Aの時間当たり限界利益は(30,000−18,000)÷8＝1,500円、Bは(25,000−10,000)÷12＝1,250円。Aを1,875個製造する場合の限界利益は22,500,000円で、固定費15,000,000円を差し引くと7,500,000円になる。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0009','リスク対応','JIS Q 27000:2019（情報セキュリティマネジメントシステム－用語）におけるリスク対応についての説明として、適切なものはどれか。','DM-A-24-03-02','ipa_past','出典：令和7年度 秋期 システム監査技術者試験 午前Ⅱ 問19','[{"id": 1, "body": "リスク及びその大きさが受容可能か否かを決定するために、リスク分析の結果をリスク基準と比較するプロセス"}, {"id": 2, "body": "リスクの特質を理解し、リスクレベルを決定するプロセス"}, {"id": 3, "body": "リスクの発見、認識及び記述を行うプロセス"}, {"id": 4, "body": "リスクを修正するプロセス"}]'::jsonb,4,'リスク対応はリスクを修正するプロセスに対応する。アはリスク評価、イはリスク分析、ウはリスク特定の説明。規格由来の表現は公開前の権利確認対象とする。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0010','需要予測と時系列','様々な需要予測モデルのもととなっている時系列モデルに関する記述のうち、適切なものはどれか。','DM-A-09-03-04','ipa_past','出典：令和7年度 春期 応用情報技術者試験 午前 問74','[{"id": 1, "body": "移動平均法では、平均する期間を長くするほど、短期的な需要の変化の影響を大きく受ける。"}, {"id": 2, "body": "移動平均法は、長期的な需要のトレンドを把握するのには向かないが、直近の需要の変化を把握するのに向いている。"}, {"id": 3, "body": "指数平滑法では、平滑化定数の値が0%に近いほど直前の実績値を重視し、100%に近いほど過去の実績値を重視する。"}, {"id": 4, "body": "指数平滑法は、過去の実績値よりも直近の実績値を用いるほど予測の精度が向上すると考えられる場合に有効な手法である。"}]'::jsonb,4,'単純指数平滑法では平滑化定数が大きいほど直近の実績を強く反映する。移動平均の期間を長くすると短期変動は平滑化される。原問の選択肢ではエが適切。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0011','購買データの関連性','データ分析手法の一つである、アソシエーション分析はどれか。','DM-A-09-02-10','ipa_past','出典：令和7年度 秋期 応用情報技術者試験 午前 問63','[{"id": 1, "body": "結果となる数値（目的変数）と要因となる数値（説明変数）との関係性について、最小二乗法を用いて分析する。気温の変化が売行きにどの程度影響するかなどの事象の予測に用いることができる。"}, {"id": 2, "body": "商品を購買するときの関連性や同時性などのルールを購買データによって見いだす。データ間の統計的なパターンや、意味のある関連性を抽出する。信頼度、支持度及びリフト値によってルールを評価し、有効性を確認する。"}, {"id": 3, "body": "多数の変数の情報（観測変数）に存する共通因子を仮定して、モデル化して分析する。共通因子を見つけることによってデータの数が増加しても複雑になることを防ぎ、現象を分かりやすく捉えることができる。"}, {"id": 4, "body": "多数の変数の情報（観測変数）をできるだけ少ない指標や次元（合成変数）で要約する。データのもつ情報をできる限り損なわずに全体の傾向を可視化することができる。"}]'::jsonb,2,'アソシエーション分析では一緒に購入される商品などの関連ルールを見つける。支持度・信頼度・リフト値を用いる説明が対応する。アは回帰、ウは因子分析、エは主成分分析の説明。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0012','部品制約と利益最大化','製品X、Yを1台製造するのに必要な部品数は、表のとおりである。製品1台当たりの利益がX、Yともに1万円のとき、利益は最大何万円になるか。ここで、部品Aは120個、部品Bは60個まで使えるものとする。','DM-A-09-03-02','ipa_past','出典：令和7年度 秋期 応用情報技術者試験 午前 問75','[{"id": 1, "body": "30"}, {"id": 2, "body": "40"}, {"id": 3, "body": "45"}, {"id": 4, "body": "60"}]'::jsonb,3,'Xの台数をx、Yをyとすると3x＋2y≦120、x＋2y≦60。両制約の交点はx＝30、y＝15で45万円。軸上の最大値40万円、30万円より大きく、最大値は45万円となる。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0013','著作権の保護対象','著作権法において、保護の対象とな̲り̲得̲な̲い̲も̲の̲はどれか。','DM-A-28-01-03','ipa_past','出典：令和7年度 秋期 応用情報技術者試験 午前 問78','[{"id": 1, "body": "インターネットで公開されたフリーソフトウェア"}, {"id": 2, "body": "ソフトウェアの操作マニュアル"}, {"id": 3, "body": "データベース"}, {"id": 4, "body": "プログラム言語や規約（プログラム言語の用法についての特別の約束）"}]'::jsonb,4,'原試験の正答はエ。プログラム言語や規約は著作権法の当該保護対象から除かれる。無料公開というだけで著作権がなくなるわけではない。また、データベースは情報の選択や体系的構成に創作性があれば保護され得る。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0014','有効顧客の共通定義','営業部は直近90日以内に購入した顧客を、サポート部は契約が有効な顧客を「有効顧客」と呼んでいる。各部門の指標を維持しながら、全社報告で時系列比較ができるようにする方法はどれか。','DM-A-08-03-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "全社報告には、報告月に集計を担当した部門の定義を使用する。", "explanation": "担当部門が変わると測定対象も変わる。"}, {"id": 2, "body": "全社報告用の指標を別に定義し、適用日と定義変更時の比較方法を記録する。", "explanation": "測定対象を統一し、変更の前後でどの数値が比較できるか確認できる。"}, {"id": 3, "body": "部門別の顧客数を合計し、両方の部門に存在する顧客を除いて全社指標とする。", "explanation": "重複排除だけでは、全社として誰を有効とするか決まらない。"}, {"id": 4, "body": "集計ツールを統一し、全社の各部門で従来どおりの抽出条件を使用する。", "explanation": "ツールの統一だけでは定義の違いが残る。"}]'::jsonb,2,'測定対象を統一し、変更の前後でどの数値が比較できるか確認できる。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0015','欠損と平均年齢の推定','紙とWebで実施したアンケートで、年齢欄の未回答が紙に多かった。居住地域は全件で確認できる。全回答者の平均年齢を推定するため、年齢の欠損をどう扱うか決める前に行う分析として、最も適切なものはどれか。','DM-A-08-04-02','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "経路別の未回答件数を比較し、件数が少ない経路の回答を中心に年齢を集計する。", "explanation": "未回答件数は経路の回答者数にも左右される。件数だけで経路を選ぶと、回答者の構成が偏る可能性がある。"}, {"id": 2, "body": "年齢が入力された回答だけで経路別の平均を求め、その差を根拠に欠損の影響を判定する。", "explanation": "観測できた年齢の平均だけでは、未回答者と回答者の構成が異なるかを調べられない。"}, {"id": 3, "body": "経路別の未回答率を求め、年齢の回答者と未回答者で居住地域の分布を比べる。", "explanation": "欠損が起きた経路や属性の偏りを点検できる。地域を比較しても未回答者の年齢は確定しないので、除外・補完の仮定によって推定値がどう変わるかも確認する。"}, {"id": 4, "body": "各経路の回答済み年齢を同数ずつ抽出し、経路別の標本数をそろえて平均を求める。", "explanation": "標本数をそろえても、欠損が特定の属性に偏っていれば、その偏りは残る。母集団の経路構成とも一致するとは限らない。"}]'::jsonb,3,'欠損が起きた経路や属性の偏りを点検できる。地域を比較しても未回答者の年齢は確定しないので、除外・補完の仮定によって推定値がどう変わるかも確認する。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0016','ビジネスメタデータ','売上データのデータカタログに登録する情報のうち、ビジネスメタデータとして最も適切なものはどれか。','DM-A-08-05-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "売上金額は返品を控除した税抜金額である、という業務上の定義"}, {"id": 2, "body": "データベース製品のパッチ番号"}, {"id": 3, "body": "列を格納する物理ファイルのパス"}, {"id": 4, "body": "前回のバックアップジョブの実行時間"}]'::jsonb,1,'ビジネスメタデータはデータの業務上の意味や定義を表す。ほかの選択肢は技術情報や運用情報であり、売上金額の業務上の意味を説明していない。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0017','生成AIが引用した資料の確認','生成AIは、社内手順書の2024年版を引用して「申請は不要」と回答した。現在の手続を案内するとき、回答の根拠を確かめる方法はどれか。','DM-A-27-02-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "2024年版の文書が存在することを確認し、その回答を採用する。", "explanation": "資料の実在だけでは、その規定が現在も適用されるとは確認できない。"}, {"id": 2, "body": "別の生成AIにも同じ手順書名を提示し、結論が一致した場合に採用する。", "explanation": "AI間の一致は元資料との整合を保証しない。"}, {"id": 3, "body": "2024年版と最新版の目次を比較し、関連する章の名称が同じなら採用する。", "explanation": "章名が同じでも規定は変更され得る。"}, {"id": 4, "body": "適用対象に該当する最新版の規定を確認し、回答の結論が該当箇所に裏付けられているかを調べる。", "explanation": "適用される文書の版と、該当規定が結論を支持するかの両方を確認している。"}]'::jsonb,4,'適用される文書の版と、該当規定が結論を支持するかの両方を確認している。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0018','同意方式と記録の組合せ','販促メールの配信は、顧客が目的を確認して事前に同意した場合だけ行う。後から、どの目的にいつ同意したか、また同意が撤回されたかを確認する。配信方式と保持する記録の組合せはどれか。','DM-A-29-01-01','ai_original','AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。','[{"id": 1, "body": "オプトイン方式 ／ 現在の配信可否だけを記録する。", "explanation": "事前同意方式は合っているが、現在の状態だけでは過去の目的や日時を確認できない。"}, {"id": 2, "body": "オプトイン方式 ／ 対象の目的、同意日時及び撤回履歴を記録する。", "explanation": "事前同意の方式と、同意・撤回を追跡するための記録がそろっている。"}, {"id": 3, "body": "オプトアウト方式 ／ 対象の目的、同意日時及び撤回履歴を記録する。", "explanation": "記録内容は適切だが、事前同意による配信はオプトインである。"}, {"id": 4, "body": "オプトアウト方式 ／ 現在の配信可否だけを記録する。", "explanation": "方式が異なり、必要な履歴も確認できない。"}]'::jsonb,2,'事前同意の方式と、同意・撤回を追跡するための記録がそろっている。',true) on conflict do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0019','ディープラーニングの特徴','AIにおけるディープラーニングに関する記述として、最も適切なものはどれか。','DM-A-10-02-03','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問3（句読点を統一。解説は独自作成）','[{"id": 1, "body": "あるデータから結果を求める処理を、人間の脳神経回路のように多層の処理を重ねることによって、複雑な判断をできるようにする。"}, {"id": 2, "body": "大量のデータからまだ知られていない新たな規則や仮説を発見するために、想定値から大きく外れている例外事項を取り除きながら分析を繰り返す手法である。"}, {"id": 3, "body": "多様なデータや大量のデータに対して、三段論法、統計的手法やパターン認識手法を組み合わせることによって、高度なデータ分析を行う手法である。"}, {"id": 4, "body": "知識がルールに従って表現されており、演繹手法を利用した推論によって有意な結論を導く手法である。"}]'::jsonb,1,'ディープラーニングは、多層のニューラルネットワークによってデータの特徴を学習する手法である。単に大量のデータを使うことや、ルールに基づく推論と同じ意味ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0020','連関図による原因の整理','分析対象としている問題に数多くの要因が関係し、それらが相互に絡み合っているとき、原因と結果、目的と手段といった関係を追求していくことによって、因果関係を明らかにし、解決の糸口をつかむための図はどれか。','DM-A-09-03-03','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問74（句読点を統一。解説は独自作成）','[{"id": 1, "body": "アローダイアグラム"}, {"id": 2, "body": "パレート図"}, {"id": 3, "body": "マトリックス図"}, {"id": 4, "body": "連関図"}]'::jsonb,4,'連関図は、問題に関係する要因を因果関係で結び、複雑に絡む関係を整理する。パレート図は件数などの大きい項目を把握し、マトリックス図は二つ以上の要素の対応関係を整理するために用いる。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0021','要配慮個人情報','個人情報のうち、個人情報保護法における要配慮個人情報に該当するものはどれか。','DM-A-29-01-01','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問80（句読点を統一。解説は独自作成）','[{"id": 1, "body": "個人情報の取得時に、本人が取扱いの配慮を申告することによって設定される情報"}, {"id": 2, "body": "個人に割り当てられた、運転免許証、クレジットカードなどの番号"}, {"id": 3, "body": "生存する個人に関する、個人を特定するために用いられる勤務先や住所などの情報"}, {"id": 4, "body": "本人の病歴、犯罪の経歴など不当な差別や不利益を生じさせるおそれのある情報"}]'::jsonb,4,'要配慮個人情報には、病歴や犯罪の経歴など、取扱いに特に配慮を要する情報が含まれる。本人が配慮を申し出た情報すべてを意味するのではない。番号や住所は個人情報になり得るが、それだけで要配慮個人情報に該当するとは限らない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0022','交差検証による汎化性能の評価','AIにおける教師あり学習での交差検証に関する記述はどれか。','DM-A-10-02-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問2（句読点を統一。解説は独自作成）','[{"id": 1, "body": "過学習を防ぐために、回帰モデルに複雑さを表すペナルティ項を加え、訓練データへ過剰に適合しないようにモデルを調整する。"}, {"id": 2, "body": "学習の精度を高めるために、複数の異なるアルゴリズムのモデルで学習し、学習の結果は組み合わせて評価する。"}, {"id": 3, "body": "学習モデルの汎化性能を高めるために、単一のモデルで関連する複数の課題を学習することによって、課題間に共通する要因を獲得する。"}, {"id": 4, "body": "学習モデルの汎化性能を評価するために、データを複数のグループに分割し、一部を学習に残りを評価に使い、順にグループを入れ替えて学習と評価を繰り返す。"}]'::jsonb,4,'交差検証は、データを分割し、学習用と評価用を入れ替えて性能を評価する方法である。未知のデータへの対応力である汎化性能を見積もる。ほかの選択肢は順に正則化、アンサンブル学習、マルチタスク学習の説明である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0023','オープンデータ・バイ・デザイン','官民データ活用推進基本法などに基づいて進められているオープンデータバイデザインに関して、行政機関における取組についての記述として、適切なものはどれか。','DM-A-09-02-01','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問62（句読点を統一。解説は独自作成）','[{"id": 1, "body": "行政機関が保有する個人情報を産業振興などの目的でオープン化する場合は、データ公開に先立ち、個人情報保護委員会への届出が義務化されている。"}, {"id": 2, "body": "行政機関において収集・蓄積された既存のデータが公開される場合、営利目的の利用は許されておらず、非営利の用途に限って利用が認められている。"}, {"id": 3, "body": "行政機関における情報システムの設計において、情報セキュリティを確保する観点から、公開するデータの用途を行政機関同士の相互利用に限定している。"}, {"id": 4, "body": "対象となる行政データを、二次利用や機械判読に適した形態で無償公開することを前提に、情報システムや業務プロセスの企画、整備及び運用を行っている。"}]'::jsonb,4,'オープンデータ・バイ・デザインでは、データ公開を後から付け足すのではなく、企画や設計の段階から二次利用や機械判読を考慮する。オープンデータは営利利用や行政機関以外の利用を一律に排除するものではなく、個人情報を無条件に公開する考え方でもない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0024','ECRSによる業務改善','業務改善の4原則としてのEliminate、Combine、Rearrange、Simplifyは、業務改善を実現する上での視点を示すものである。次の業務改善例のうち、Rearrangeを適用したものはどれか。','DM-A-09-03-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問63（句読点を統一。解説は独自作成）','[{"id": 1, "body": "経費精算申請業務において、決裁に不要な人を申請フローから外し、決裁までに要する時間を短縮した。"}, {"id": 2, "body": "商品配送ルートを可視化した結果、移動距離の無駄が発見された。そこで、配送順を入れ替えることで、一日に配送できる件数を向上させた。"}, {"id": 3, "body": "表計算ソフト上で各項目を手入力していたが、一つの項目を入力すれば他の関連項目が自動計算できるように関数を設定し、作業効率を向上させた。"}, {"id": 4, "body": "複数部門が集まる会議の議事録を、各部門のスタッフが、それぞれ独自に作成していた。各部門での作成をやめ、代表者1名が作成し、部門間で共有した。"}]'::jsonb,2,'Rearrangeは、作業の順序や配置を入れ替えて改善する視点である。配送順の変更が該当する。ほかの選択肢は順にEliminate（排除）、Simplify（簡素化）、Combine（結合）に対応する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0025','ファインチューニング','生成AIのビジネス活用において、独自のデータを学習させることにより基盤モデルを自社の業務やサービスに特化したモデルへとカスタマイズすることを何と呼ぶか。','DM-A-10-03-02','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問71（句読点を統一。解説は独自作成）','[{"id": 1, "body": "アノテーション"}, {"id": 2, "body": "クラスタリング"}, {"id": 3, "body": "ファインチューニング"}, {"id": 4, "body": "プロンプトエンジニアリング"}]'::jsonb,3,'ファインチューニングは、学習済みのモデルに追加のデータで学習を行い、用途に適合させる方法である。プロンプトエンジニアリングは入力する指示を工夫する方法であり、モデルの追加学習とは区別する。アノテーションはデータへのラベル付け、クラスタリングは類似するデータのグループ化を指す。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0026','ベイズ統計の考え方','ベイズ統計の説明として、適切なものはどれか。','DM-A-09-02-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問76（句読点を統一。解説は独自作成）','[{"id": 1, "body": "経済統計に関する国際条約に基づいて、貿易実態を正確に把握し、国の経済政策や企業の経済活動の資料とすることを目的とした指標を作成する統計手法"}, {"id": 2, "body": "事前分布・事後分布といった確率に関する考え方に基づいて体系化されたものであり、機械学習、迷惑メールフィルターなどに利用されている統計理論"}, {"id": 3, "body": "収集されたデータの代表値である平均値・中央値・最頻値を求めたり、度数分布表やヒストグラムを作成したりすることによって、データの特徴を捉える統計理論"}, {"id": 4, "body": "ビッグデータの収集・分析に当たり、分析結果の検証可能性を確保し、複数の分析結果を比較可能とするために、対象をオープンデータに限定する統計手法"}]'::jsonb,2,'ベイズ統計では、事前の確率に新たな観測結果を反映し、事後の確率へ更新する。迷惑メール判定などにも利用される。代表値やヒストグラムによってデータの特徴を要約する説明は記述統計に対応する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0027','プログラムと著作権','著作権法で保護されるものはどれか。','DM-A-28-01-03','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問78（句読点を統一。解説は独自作成）','[{"id": 1, "body": "アルゴリズム"}, {"id": 2, "body": "コンパイラのプログラム"}, {"id": 3, "body": "プログラム言語"}, {"id": 4, "body": "プロトコル"}]'::jsonb,2,'プログラムは、創作性のある具体的な表現として著作物になり得る。アルゴリズムという解法そのもの、プログラム言語、規約であるプロトコルとは区別する。原試験ではコンパイラのプログラムが正答である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0028','フィルターバブル','SNSやWeb検索などに関して、イーライ・パリサーが提唱したフィルターバブルの記述として、適切なものはどれか。','DM-A-27-01-02','ipa_past','出典：令和6年度 春期 ITストラテジスト試験 午前Ⅱ 問17（句読点を統一。解説は独自作成）','[{"id": 1, "body": "PCやスマートフォンなど、使用する機器の性能やソフトウェアの機能に応じて、利用者は情報へのアクセスにフィルターがかかっており、様々な格差が生じている。"}, {"id": 2, "body": "SNS、Webの一般のインターネット利用者が発信する情報が増えたことによって、Web検索の結果は非常に膨大なものとなり、個人による適切な情報収集が難しくなった。"}, {"id": 3, "body": "広告収入を目的に、事実とは異なるフィルターのかかったニュースがSNSなどを通じて発信されるようになったので、正確な情報を検索することが困難になった。"}, {"id": 4, "body": "利用者の属性・行動などに応じ、好ましいと考えられる情報がより多く表示され、利用者は実社会とは隔てられたパーソナライズされた情報空間へと包まれる。"}]'::jsonb,4,'フィルターバブルは、個人に合わせた情報の選別によって、接する情報が偏り、異なる見方に触れにくくなる現象である。機器による情報格差、情報量の増大、偽情報の発信それ自体とは区別する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0029','親和図による情報の整理','親和図の特徴はどれか。','DM-A-09-03-05','ipa_past','出典：令和6年度 春期 ITストラテジスト試験 午前Ⅱ 問19（句読点を統一。解説は独自作成）','[{"id": 1, "body": "原因と結果を対比させた図式表現であり、不良原因の追及に用いられる。"}, {"id": 2, "body": "錯綜した問題点や、まとまっていない意見、アイディアなどを整理し、まとめるために用いられる。"}, {"id": 3, "body": "二つ以上の変数の相互関係を表すのに役立つ。"}, {"id": 4, "body": "分布の形、目標値からのばらつき状態などから、製品の品質の状態が規格値に対して満足しているものかなどを判断するために用いられる。"}]'::jsonb,2,'親和図は、集めた意見や情報を内容の近さによってグループ化して整理する。ほかの選択肢は順に特性要因図、マトリックス図、ヒストグラムの用途に対応する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0030','AI学習と非享受目的の著作物利用','公衆への提供などが行われた他人の著作物をAIの学習データとして利用する行為に関して、著作権法に照らして適切なものはどれか。ただし、著作物の利用は、AIによる情報解析の範囲で行われ、著作物に表現された思想又は感情を享受することを目的とするものではない。また、日本国内で作成された著作物を日本国内で利用する場合であり、利用者と著作権者との間で特段の契約は存在しないものとする。','DM-A-28-01-05','ipa_past','出典：令和6年度 春期 ITストラテジスト試験 午前Ⅱ 問22（句読点を統一。解説は独自作成）','[{"id": 1, "body": "他人の著作物から情報を抽出してAIに学習させる行為は、どのような条件においても、一切禁止されている。"}, {"id": 2, "body": "著作権者の許諾が得られた場合に限って、著作権者との合意の範囲内において、AIの学習に利用できる。"}, {"id": 3, "body": "著作権者の利益を不当に害さない場合、その必要と認められる限度において、商業利用であるか否かを問わず、著作権者の許諾なくAIの学習に利用できる。"}, {"id": 4, "body": "著作権者の利益を不当に害する場合及び商業利用の場合を除いて、著作権者の許諾なくAIの学習に利用できる。"}]'::jsonb,3,'問題文の非享受目的などの前提では、著作権法第30条の4により、必要と認められる限度で利用できる場合がある。商業利用であることだけで一律に除外されるわけではない。著作権者の利益を不当に害する場合は対象外であり、AI学習全般が無条件に自由という意味ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0031','職務著作と公表名義','著作権法及び関連法令によれば、職務著作の要件のうち、プログラムの著作物の場合は満たす必要がなく、プログラム以外の著作物の場合は満たす必要があるものはどれか。','DM-A-28-01-03','ipa_past','出典：令和6年度 秋期 システム監査技術者試験 午前Ⅱ 問13（句読点を統一。解説は独自作成）','[{"id": 1, "body": "著作権が作成者に帰属するとの取決めがないこと"}, {"id": 2, "body": "法人等が自己の著作の名義の下に公表していること"}, {"id": 3, "body": "法人等の業務に従事する者が作成していること"}, {"id": 4, "body": "法人等の発意に基づいていること"}]'::jsonb,2,'職務著作では法人等の発意や職務上の作成などの要件が問題になる。プログラムの著作物については、法人等の名義で公表するという要件は課されない。プログラム以外の著作物との違いを問う問題であり、単に会社で作ったものすべてが自動的に職務著作になるという意味ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0032','エラープルーフによるミスの予防','ヒューマンエラーに起因する障害の低減策の一つに、エラープルーフ化がある。エラープルーフ化の五つの原理のうち、作業ミスによるエラーの発生を未然に防ぐための原理の組みはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0033','ベイジアンフィルター','迷惑メールの検知手法であるベイジアンフィルターの説明はどれか。','DM-A-10-02-03','ipa_past','出典：令和6年度 秋期 データベーススペシャリスト試験 午前Ⅱ 問20（句読点を統一。解説は独自作成）','[{"id": 1, "body": "信頼できるメール送信元を許可リストに登録しておき、許可リストにないメール送信元からの電子メールは迷惑メールと判定する。"}, {"id": 2, "body": "電子メールが正規のメールサーバから送信されていることを検証し、迷惑メールであるかどうかを判定する。"}, {"id": 3, "body": "電子メールの第三者中継を許可しているメールサーバを登録したデータベースの掲載情報を基に、迷惑メールであるかどうかを判定する。"}, {"id": 4, "body": "利用者が振り分けた迷惑メールと正規のメールから特徴を学習し、迷惑メールであるかどうかを統計的に判定する。"}]'::jsonb,4,'ベイジアンフィルターは、分類済みのメールに含まれる語句などの特徴を学習し、迷惑メールである確率を用いて判定する。送信元の許可リストや、送信元サーバの正当性の確認だけで分類する手法ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0034','リスク特定で考慮する資産の価値','JIS Q 31000:2019（リスクマネジメント－指針）において、リスク特定で考慮することが望ましいとされている事項はどれか。','DM-A-24-03-01','ipa_past','出典：令和6年度 春期 応用情報技術者試験 午前 問40（句読点を統一。解説は独自作成）','[{"id": 1, "body": "結果の性質及び大きさ"}, {"id": 2, "body": "残留リスクが許容可能かどうかの判断"}, {"id": 3, "body": "資産及び組織の資源の性質及び価値"}, {"id": 4, "body": "事象の起こりやすさ及び結果"}]'::jsonb,3,'リスク特定では、保護すべき資産や組織の資源の性質・価値を把握し、リスクを見いだす。結果の大きさや起こりやすさの検討はリスク分析、残留リスクの許容可否の判断は評価・受容の文脈と区別する。公式正答は資産及び組織の資源の性質及び価値である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0035','ディープフェイクを悪用した攻撃','ディープフェイクを悪用した攻撃に該当するものはどれか。','DM-A-27-02-01','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問39（句読点を統一。解説は独自作成）','[{"id": 1, "body": "AI技術によって加工したCEOの音声を使用して従業員に電話をかけ、指定した銀行口座に送金するよう指示した。"}, {"id": 2, "body": "企業のPCをランサムウェアに感染させ、暗号化したデータを復号するための鍵と引き換えに、指定した方法で暗号資産を送付するよう指示した。"}, {"id": 3, "body": "企業の秘密情報を含むデータを不正に取得したと誤認させる電子メールを従業員に送付し、不正に取得したデータを公開しないことと引き換えに、指定した方法で暗号資産を送付するよう指示した。"}, {"id": 4, "body": "ディープウェブにて入手した認証情報でCEOの電子メールアカウントに不正にログインして偽りの電子メールを従業員に送付し、指定した銀行口座に送金するよう指示した。"}]'::jsonb,1,'ディープフェイクは、AIによって実在の人物に似た音声や映像などを生成・加工する技術である。CEOに似せた加工音声を使う手口が該当する。ランサムウェアや認証情報の不正利用とは異なる。音声や映像だけで本人と断定せず、別の経路で確認することが重要である。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0036','表の構造から取得できる情報','化粧品の製造を行っているA社では、販売代理店を通じて商品販売を行っている。今後の販売戦略に活用するために、次の三つの表を設計した。これらの表を用いるだけでは得̲る̲こ̲と̲の̲で̲き̲な̲い̲情̲報̲はどれか。','DM-A-17-02-01','ipa_past','出典：令和6年度 秋期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）','[{"id": 1, "body": "商品ごとの販売数量の日別差異"}, {"id": 2, "body": "性別ごとの売れ筋商品"}, {"id": 3, "body": "販売代理店ごとの購入者数の日別差異"}, {"id": 4, "body": "販売代理店ごとの売れ筋商品"}]'::jsonb,3,'商品購入の表には購入日がないため、購入者を日付ごとに数えることができない。日別販売の表には日付があるが、購入した顧客を識別する項目がない。性別ごとの集計は顧客IDで関連付けて行える。表の項目と関連から、得られる情報と不足する情報を判断する。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0037','データガバナンスを確保する理由','組織においてデータガバナンスを確保することが重要である背景及び理由として、最も適切なものはどれか。','DM-A-08-03-01','ipa_sample','出典：IPA データマネジメント試験（仮称）科目A サンプル問題 問1（2026年6月公開。読点を統一。解説は独自作成）','[{"id": 1, "body": "データの活用が広がる中で、組織内のデータの品質やセキュリティを維持し、意思決定の精度向上、法令遵守などを実現することによって、組織の価値と信頼を高めるため。"}, {"id": 2, "body": "データの活用が広がる中で、組織内のデータを部門ごとに分断（サイロ化）し、保有するデータの内容を秘匿にすることによって、部門を越えたデータアクセスを統制するため。"}, {"id": 3, "body": "デジタル技術が高度化する中で、データ基盤を導入する際の評価基準及びプロセスを組織内で確立することによって、情報システム部によるITコントロールを強化するため。"}, {"id": 4, "body": "デジタル技術が高度化する中で、データを処理する人手の業務を自動化ツールに置き換えるデジタル化を推進することによって、データ処理に関わる人的コストを最適化するため。"}]'::jsonb,1,'データガバナンスは、組織全体のデータの品質やセキュリティ、法令遵守などを支え、価値ある意思決定と組織への信頼につなげるための統制である。部門間のサイロ化を進めることではない。IT基盤の評価や業務の自動化だけに目的を限定する説明も適切ではない。',true) on conflict(id) do nothing;
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0038','データ品質を低下させる対応','AIやBIツールの処理対象となるデータは、そのデータ品質を適切に維持することが重要である。データ品質の劣化につながる望ましくない対応だけを全て挙げた組合せはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values('DMQ-0039','ビジネスメタデータの継続的な整備','メタデータを次のa〜cの三つに分類したとき、特にa（ビジネス及び業務に関するメタデータ）の整備が組織にとって課題となることが多い。この課題を解決する方法として、最も適切なものはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values
  ('DMQ-0040','項目が変動するJSONデータの格納','JSON形式で表現される図1、図2のような商品データを複数のWebサービスから取得し、商品データベースとして蓄積する際のデータの格納方法に関する記述のうち、適切なものはどれか。ここで、商品データの取得元となるWebサービスは随時変更され、項目数や内容は予測できない。したがって、商品データベースの検索時に使用するキーにはあらかじめ制限を設けない。','DM-A-09-01-01','ipa_past','出典：令和5年度 春期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）','[{"id": 1, "body": "階層型データベースを使用し、項目名を上位階層とし、値を下位階層とした2階層でデータを格納する。"}, {"id": 2, "body": "グラフデータベースを使用し、商品データの項目名の集合から成るノードと値の集合から成るノードを作り、二つのノードを関係付けたグラフとしてデータを格納する。"}, {"id": 3, "body": "ドキュメントデータベースを使用し、項目構成の違いを区別せず、商品データ単位にデータを格納する。"}, {"id": 4, "body": "関係データベースを使用し、商品データの各項目名を個別の列名とした表を定義してデータを格納する。"}]'::jsonb,3,'商品をドキュメント単位で保存すれば、取得先によってフィールドが違っていても元のまとまりを保てる。新たな項目を追加するたびに全商品の表定義を更新する必要もない。',true),
  ('DMQ-0041','所属履歴の多重度','UMLを用いて表した図のデータモデルのa、bに入れる多重度はどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values
  ('DMQ-0050','3層スキーマの内部スキーマ','ANSI/SPARC 3層スキーマモデルにおける内部スキーマの設計に含まれるものはどれか。','DM-A-17-01-01','ipa_past','出典：令和4年度 春期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）','[{"id": 1, "body": "SQL問合せ応答時間の向上を目的としたインデックスの定義"}, {"id": 2, "body": "エンティティ間の“1対多”、“多対多”などの関連を明示するE-Rモデルの作成"}, {"id": 3, "body": "エンティティ内やエンティティ間の整合性を保つための一意性制約や参照制約の設定"}, {"id": 4, "body": "データの冗長性を排除し、更新の一貫性と効率性を保持するための正規化"}]'::jsonb,1,'内部スキーマは、データの格納やアクセスの物理的な方式を定める。インデックスは、問い合わせ時のアクセス経路を改善するために設計する。',true),
  ('DMQ-0051','第1・第2・第3正規形','第1、第2、第3正規形とリレーションの特徴a、b、cの組合せのうち、適切なものはどれか。
insert into study.questions(id,title,body,category_id,origin,source,choices,correct,explanation,published) values
  ('DMQ-0062','グラフ指向データベース','NoSQLの一種である、グラフ指向DBの特徴として、適切なものはどれか。','DM-A-09-01-01','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）','[{"id": 1, "body": "データ項目の値として階層構造のデータをドキュメントとしてもつことができる。また、ドキュメントに対しインデックスを作成することもできる。"}, {"id": 2, "body": "ノード、リレーション、プロパティで構成され、ノード間をリレーションでつないで構造化する。ノード及びリレーションはプロパティをもつことができる。"}, {"id": 3, "body": "一つのキーに対して一つの値をとる形をしている。値の型は定義されていないので、様々な型の値を格納することができる。"}, {"id": 4, "body": "一つのキーに対して複数の列をとる形をしている。関係データベースとは異なり、列の型は固定されていない。"}]'::jsonb,2,'グラフ指向データベースは、人物や商品などをノード、購入や友人関係などをノード間の関係として格納する。つながりをたどる問い合わせに向く。',true),
  ('DMQ-0063','受注を記録するUMLモデル','商品の注文を記録するクラス（顧客、商品、注文、注文明細）の構造を概念データモデルで表現する。a〜dに入れるべきクラス名の組合せはどれか。ここで、顧客は何度も注文を行い、一度に一つ以上の商品を注文でき、注文明細はそれぞれ1種類の商品に対応している。また、モデルの表記にはUMLを用いる。','DM-A-17-02-02','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）','[{"id": 1, "body": "顧客　注文　注文明細　商品"}, {"id": 2, "body": "商品　注文　注文明細　顧客"}, {"id": 3, "body": "注文　注文明細　顧客　商品"}, {"id": 4, "body": "注文明細　商品　注文　顧客"}]'::jsonb,1,'一人の顧客は複数の注文を持ち、一つの注文は複数の明細を持てる。各明細は一つの商品を指し、同じ商品を複数の明細で参照できる。',true),
  ('DMQ-0064','データレイクの格納方法','データレイクの特徴はどれか。','DM-A-09-01-01','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問31（句読点を統一。解説は独自作成）','[{"id": 1, "body": "大量のデータを分析し、単なる検索だけでは分からない隠れた規則や相関関係を見つけ出す。"}, {"id": 2, "body": "データウェアハウスに格納されたデータから特定の用途に必要なデータだけを取り出し、構成する。"}, {"id": 3, "body": "データウェアハウスやデータマートからデータを取り出し、多次元分析を行う。"}, {"id": 4, "body": "必要に応じて加工するために、データを発生したままの形で格納する。"}]'::jsonb,4,'データレイクでは、さまざまな形式のデータを受け入れ、用途が決まってから必要な構造に変換できる。例えばセンサー記録と画像を受け取った形式のまま保存しておける。',true),
  ('DMQ-0065','協調フィルタリングによる推薦','レコメンデーション（お勧め商品の提案）の例のうち、協調フィルタリングを用いたものはどれか。','DM-A-09-02-10','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問63（句読点を統一。解説は独自作成）','[{"id": 1, "body": "多くの顧客の購買行動の類似性を相関分析などによって求め、顧客Aに類似した顧客Bが購入している商品を顧客Aに勧める。"}, {"id": 2, "body": "カテゴリ別に売れ筋商品のランキングを自動抽出し、リアルタイムで売れ筋情報を発信する。"}, {"id": 3, "body": "顧客情報から、年齢、性別などの人口動態変数を用い、“20代男性”、“30代女性”などにセグメント化した上で、各セグメント向けの商品を提示する。"}, {"id": 4, "body": "野球のバットを購入した人に野球のボールを勧めるなど商品間の関連に着目して、関連商品を提示する。"}]'::jsonb,1,'利用者ベースの協調フィルタリングは、購買や評価の履歴が似た人の行動から、対象者がまだ利用していない商品への関心を推定する。',true),
  ('DMQ-0066','系統図法で目的と手段を整理する','系統図法の活用例はどれか。','DM-A-09-03-03','ipa_past','出典：令和3年度 春期 応用情報技術者試験 午前 問76（句読点を統一。解説は独自作成）','[{"id": 1, "body": "解決すべき問題を端か中央に置き、関係する要因を因果関係に従って矢印でつないで周囲に並べ、問題発生に大きく影響している重要な原因を探る。"}, {"id": 2, "body": "結果とそれに影響を及ぼすと思われる要因との関連を整理し、体系化して、魚の骨のような形にまとめる。"}, {"id": 3, "body": "事実、意見、発想を小さなカードに書き込み、カード相互の親和性によってグループ化して、解決すべき問題を明確にする。"}, {"id": 4, "body": "目的を達成するための手段を導き出し、更にその手段を実施するための幾つかの手段を考えることを繰り返し、細分化していく。"}]'::jsonb,4,'系統図法では目的を起点とし、「何をすれば達成できるか」を繰り返し考えて手段を枝分かれさせる。抽象的な目標を具体的な行動に落とし込める。',true),
  ('DMQ-0067','関係演算の和集合','関係Rと関係Sに対して、関係Xを求める関係演算はどれか。','DM-A-17-02-01','ipa_past','出典：令和3年度 秋期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）','[{"id": 1, "body": "IDで結合"}, {"id": 2, "body": "差"}, {"id": 3, "body": "直積"}, {"id": 4, "body": "和"}]'::jsonb,4,'和集合はどちらか一方にでもある行を集め、全項目が一致する重複は1行にする。IDが同じでも項目Aが異なる行は両方残る。',true),
  ('DMQ-0068','受注明細と部分従属','受注入力システムによって作成される次の表に関する記述のうち、適切なものはどれか。受注番号は受注ごとに新たに発行される番号であり、項番は1回の受注で商品コード別に連番で発行される番号である。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0072', '外部キーによる連鎖削除', '図のような関係データベースの“注文”表と“注文明細”表がある。“注文”表の行を削除すると、対応する“注文明細”表の行が、自動的に削除されるようにしたい。SQL文のON DELETE句に指定する語句はどれか。ここで、図中の実線の下線は主キーを、破線の下線は外部キーを表す。', 'DM-A-17-02-01', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "CASCADE", "explanation": "参照先の行を削除したとき、それを参照する行も連鎖して削除する。"}, {"id": 2, "body": "INTERSECT", "explanation": "二つの問合せ結果に共通する行を取り出す集合演算である。"}, {"id": 3, "body": "RESTRICT", "explanation": "参照している行が残っている場合、参照先の削除を制限する。"}, {"id": 4, "body": "UNIQUE", "explanation": "列又は列の組の値に一意性を要求する制約である。"}]'::jsonb, 1, '外部キーにON DELETE CASCADEを指定すると、参照先の注文を削除したとき、その注文を参照する明細も削除される。', 'ipa-original/DMQ-0072.png', true),
  ('DMQ-0073', '共有ロックと専有ロック', 'RDBMSのロックに関する記述のうち、適切なものはどれか。ここで、X、Yはトランザクションとする。', 'DM-A-17-01-01', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "XがA表内の特定行aに対して共有ロックを獲得しているときは、YはA表内の別の特定行bに対して専有ロックを獲得することができない。", "explanation": "行aと行bは別の行なので、行aの共有ロックだけでは行bの専有ロックを妨げない。"}, {"id": 2, "body": "XがA表内の特定行aに対して共有ロックを獲得しているときは、YはA表に対して専有ロックを獲得することができない。", "explanation": "表全体に対する専有ロックは行aを含む。行aの共有ロックが保持されている間は競合する。"}, {"id": 3, "body": "XがA表に対して共有ロックを獲得しているときでも、YはA表に対して専有ロックを獲得することができる。", "explanation": "同じ表の共有ロックと専有ロックは競合する。"}, {"id": 4, "body": "XがA表に対して専有ロックを獲得しているときでも、YはA表内の特定行aに対して専有ロックを獲得することができる。", "explanation": "表全体の専有ロックには行aも含まれ、別トランザクションの専有ロックと競合する。"}]'::jsonb, 2, 'ロックの互換性は対象範囲でも決まる。表全体に対する専有ロックの範囲には、その表の各行が含まれる。', null, true),
  ('DMQ-0074', '媒体障害からのデータベース回復', 'データベースに媒体障害が発生したときのデータベースの回復法はどれか。', 'DM-A-24-01-01', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "障害発生時、異常終了したトランザクションをロールバックする。", "explanation": "取り消しだけでは、記憶媒体から失われたデータを復元できない。"}, {"id": 2, "body": "障害発生時点でコミットしていたがデータベースの実更新がされていないトランザクションをロールフォワードする。", "explanation": "未反映の確定処理だけを再適用すると、媒体障害前に書込み済みだった更新を復元できない。"}, {"id": 3, "body": "障害発生時点でまだコミットもアボートもしていなかった全てのトランザクションをロールバックする。", "explanation": "未確定処理を取り消す手順であり、媒体から失われた確定データは戻らない。"}, {"id": 4, "body": "バックアップコピーでデータベースを復元し、バックアップ取得以降にコミットした全てのトランザクションをロールフォワードする。", "explanation": "バックアップを基点に確定済みの変更を積み直すことで、失われた更新を復元する。"}]'::jsonb, 4, '媒体障害で失われたファイルをバックアップから復元し、バックアップ時点より後に確定した更新をログで再適用する。', null, true),
  ('DMQ-0075', 'コンバージョン率', 'インターネット広告の効果指標として用いられるコンバージョン率の説明はどれか。', 'DM-A-09-01-02', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問73（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "Webサイト上で広告が表示された回数に対して、その広告がクリックされた回数の割合を示す指標である。", "explanation": "広告表示からクリックに至った割合はクリック率である。"}, {"id": 2, "body": "Webサイト上の広告から商品購入に至った顧客の1人当たりの広告コストを示す指標である。", "explanation": "購入などの成果1件当たりに掛かった費用を示している。"}, {"id": 3, "body": "Webサイト上の広告に掛けた費用の何倍の収益をその広告から得ることができたかを示す指標である。", "explanation": "広告費を基準に収益の大きさを評価する指標を説明している。"}, {"id": 4, "body": "Webサイト上の広告をクリックして訪れた人のうち会員登録や商品購入などに至った顧客数の割合を示す指標である。", "explanation": "訪問者のうち設定した目標行動に至った人の割合を測っている。"}]'::jsonb, 4, '会員登録や購入といった目標を達成した人の割合を測るのがコンバージョン率である。この問題では広告経由の訪問者が分母となる。', null, true),
  ('DMQ-0076', 'ワークサンプリング法', 'ワークサンプリング法の説明はどれか。', 'DM-A-09-02-01', 'ipa_past', '出典：令和元年度 秋期 応用情報技術者試験 午前 問75（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "観測回数・観測時刻を設定し、実地観測によって観測された要素作業数の比率などから、統計的理論に基づいて作業時間を見積もる。", "explanation": "観測した時点の作業の割合を標本として使っている。"}, {"id": 2, "body": "作業動作を基本動作にまで分解して、基本動作の時間標準テーブルから、構成される基本動作の時間を合計して作業時間を求める。", "explanation": "基本動作の既定時間を合算する方法である。"}, {"id": 3, "body": "作業票や作業日報などから各作業の実績時間を集計し、作業ごとに平均して標準時間を求める。", "explanation": "既存の実績記録を集計して平均する方法である。"}, {"id": 4, "body": "実際の作業動作そのものをストップウォッチで数回反復測定して、作業時間を調査する。", "explanation": "動作の所要時間を直接計測している。"}]'::jsonb, 1, 'ワークサンプリングでは個々の作業を連続計測せず、複数の時点で観測した作業の出現割合から時間配分を推定する。', null, true),
  ('DMQ-0077', 'SQL GRANTによる権限付与', '表に対するSQLのGRANT文の説明として、適切なものはどれか。', 'DM-A-24-02-02', 'ipa_past', '出典：令和2年度 10月 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "パスワードを設定してデータベースへの接続を制限する。", "explanation": "パスワードによる接続時の認証を説明している。"}, {"id": 2, "body": "ビューを作成して、ビューの基となる表のアクセスできる行や列を制限する。", "explanation": "表示する行や列を絞ったビューを定義する操作を説明している。"}, {"id": 3, "body": "表のデータを暗号化して、第三者がアクセスしてもデータの内容が分からないようにする。", "explanation": "データの内容を鍵で保護する暗号化の説明である。"}, {"id": 4, "body": "表の利用者に対し、表への問合せ、更新、追加、削除などの操作権限を付与する。", "explanation": "SELECTやUPDATEなど、表に対して許可する操作を指定している。"}]'::jsonb, 4, 'GRANTは指定した利用者やロールに、指定したデータベースオブジェクトへの操作権限を付与する。', null, true),
  ('DMQ-0078', '多対多の関連を表に変換', 'UMLを用いて表した図のデータモデルから、“部品”表、“納入”表及び“メーカ”表を関係データベース上に定義するときの解釈のうち、適切なものはどれか。', 'DM-A-17-02-02', 'ipa_past', '出典：令和2年度 10月 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "同一の部品を同一のメーカから複数回納入することは許されない。", "explanation": "一つの部品と一つのメーカの組に、複数の納入の行が対応しても多重度を満たす。"}, {"id": 2, "body": "“納入”表に外部キーは必要ない。", "explanation": "納入の行がどの部品・メーカの行に対応するかを外部キーで表す。"}, {"id": 3, "body": "部品番号とメーカ番号の組みを“納入”表の候補キーの一部にできる。", "explanation": "納入番号などで同じ組の複数の納入を区別できるなら、両番号を含む組を候補キーとして設計できる。"}, {"id": 4, "body": "“メーカ”表は、外部キーとして部品番号をもつことになる。", "explanation": "部品とメーカの関連は納入を介するため、メーカ表そのものに部品番号を持たせる必要はない。"}]'::jsonb, 3, '納入の各行は部品とメーカの各1行を参照する。部品番号とメーカ番号に納入を区別できる項目を組み合わせれば、候補キーを構成できる。', 'ipa-original/DMQ-0078.png', true),
  ('DMQ-0079', '関数従属と注文明細の正規化', '関係“注文記録”の属性間に①〜⑥の関数従属性があり、それに基づいて第3正規形まで正規化を行って、“商品”、“顧客”、“注文”、“注文明細”の各関係に分解した。関係“注文明細”として、適切なものはどれか。ここで、{X、Y}は、属性XとYの組みを表し、X→Yは、XがYを関数的に決定することを表す。また、実線の下線は主キーを表す。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0082', 'データディクショナリ', '関係データベース管理システム（RDBMS）のデータディクショナリに格納されるものはどれか。', 'DM-A-08-05-01', 'ipa_past', '出典：平成30年度 春期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "OSが管理するファイルの定義情報", "explanation": "OSが管理するファイルの情報は、DBのスキーマ定義とは別である。"}, {"id": 2, "body": "スキーマの定義情報", "explanation": "表や列など、データベースの構造を記述するメタデータが格納される。"}, {"id": 3, "body": "表に格納された列データの組", "explanation": "表の列データは管理対象のデータそのものである。"}, {"id": 4, "body": "表の列に付けられたインデックスの値", "explanation": "索引の定義はメタデータだが、索引の値は検索用の実データである。"}]'::jsonb, 2, '表や列など、データベースの構造を記述するメタデータが格納される。', null, true),
  ('DMQ-0083', 'キーバリュー型データベース', 'ビッグデータの基盤技術として利用されるNoSQLに分類されるデータベースはどれか。', 'DM-A-09-01-01', 'ipa_past', '出典：平成30年度 春期 応用情報技術者試験 午前 問30（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "関係データモデルをオブジェクト指向データモデルに拡張し、操作の定義や型の継承関係の定義を可能としたデータベース", "explanation": "関係モデルを拡張するオブジェクト関係データベースの説明である。"}, {"id": 2, "body": "経営者の意思決定を支援するために、ある主題に基づくデータを現在の情報とともに過去の情報も蓄積したデータベース", "explanation": "時系列の情報も蓄積して分析に使うデータウェアハウスの説明である。"}, {"id": 3, "body": "様々な形式のデータを一つのキーに対応付けて管理するキーバリュー型データベース", "explanation": "キーに対応する値を管理する方式はNoSQLの代表例である。"}, {"id": 4, "body": "データ項目の名称や形式など、データそのものの特性を表すメタ情報を管理するデータベース", "explanation": "データディクショナリなど、データの定義を管理する仕組みである。"}]'::jsonb, 3, 'キーに対応する値を管理する方式はNoSQLの代表例である。', null, true),
  ('DMQ-0084', '剰余によるハッシュ値の衝突', '自然数を除数とした剰余を返すハッシュ関数がある。値がそれぞれ571、1168、1566である三つのレコードのキー値を入力値としてこのハッシュ関数を施したところ、全てのハッシュ値が衝突した。このとき使用した除数は幾つか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成30年度 秋期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "193", "explanation": "差597は193で割り切れない。"}, {"id": 2, "body": "197", "explanation": "差597は197で割り切れない。"}, {"id": 3, "body": "199", "explanation": "差597と398がともに199の倍数なので、三つのキーの余りが等しい。"}, {"id": 4, "body": "211", "explanation": "差398は211で割り切れない。"}]'::jsonb, 3, '差597と398がともに199の倍数なので、三つのキーの余りが等しい。', null, true),
  ('DMQ-0085', 'B⁺木インデックスの範囲検索', '“部品”表のメーカコード列に対し、B⁺木インデックスを作成した。これによって、“部品”表の検索の性能改善が最も期待できる操作はどれか。ここで、部品及びメーカのデータ件数は十分に多く、“部品”表に存在するメーカコード列の値の種類は十分な数があり、かつ、均一に分散しているものとする。また、“部品”表のごく少数の行には、メーカコード列にNULLが設定されている。実線の下線は主キーを、破線の下線は外部キーを表す。', 'DM-A-17-01-01', 'ipa_past', '出典：平成30年度 秋期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "メーカコードの値が1001以外の部品を検索する。", "explanation": "除外する値が一つだけなので、多数の行が検索対象になる。"}, {"id": 2, "body": "メーカコードの値が1001でも4001でもない部品を検索する。", "explanation": "二つの値を除外しても、検索対象は広い範囲に残る。"}, {"id": 3, "body": "メーカコードの値が4001以上、4003以下の部品を検索する。", "explanation": "狭い連続範囲を索引からたどり、読み取る行を大幅に絞れる。"}, {"id": 4, "body": "メーカコードの値がNULL以外の部品を検索する。", "explanation": "NULLが少数なので、検索対象は表の大部分になる。"}]'::jsonb, 3, '狭い連続範囲を索引からたどり、読み取る行を大幅に絞れる。', 'ipa-original/DMQ-0085.png', true),
  ('DMQ-0086', 'チャットボットの用途', '顧客との接点として注目される、チャットボットの説明はどれか。', 'DM-A-10-03-01', 'ipa_past', '出典：平成30年度 秋期 応用情報技術者試験 午前 問72（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "インターネットオークションなどで、売り手と買い手の取引を安全に行うために、第三者の仲介業者が決済や商品の受渡しを行うサービスである。", "explanation": "第三者が決済や受渡しを仲介するエスクローの説明である。"}, {"id": 2, "body": "需要を予測してネットワーク設備やシステムリソースなどを計画的に調達し、需要の変動に応じて迅速にサービスを提供する考え方である。", "explanation": "需要に応じて設備や処理能力を調整する考え方である。"}, {"id": 3, "body": "商品提案から販売、アフターサービスまでの、企業と顧客との双方向の対話を、AIを活用した自動応答機能などによって実現するシステムである。", "explanation": "チャットボットは会話の形式で顧客の問いに自動応答できる。"}, {"id": 4, "body": "スマートフォンのカメラなどを通して、利用者の視界に有用な情報を重ね合わせ、現実世界での行動や認知を支援する技術である。", "explanation": "現実の視界に情報を重ねる拡張現実の説明である。"}]'::jsonb, 3, 'チャットボットは会話の形式で顧客の問いに自動応答できる。', null, true),
  ('DMQ-0087', '意味を連想できるコード', 'コードの値からデータの対象物が連想できるものはどれか。', 'DM-A-09-02-01', 'ipa_past', '出典：平成31年度 春期 応用情報技術者試験 午前 問24（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "シーケンスコード", "explanation": "連番で割り当てる方式で、連番自体は対象を表さない。"}, {"id": 2, "body": "デシマルコード", "explanation": "十進数字で分類階層を表す方式である。"}, {"id": 3, "body": "ニモニックコード", "explanation": "名称の略記など、対象を連想しやすい値を割り当てる。"}, {"id": 4, "body": "ブロックコード", "explanation": "分類ごとに番号の範囲を割り当てる方式である。"}]'::jsonb, 3, '名称の略記など、対象を連想しやすい値を割り当てる。', null, true),
  ('DMQ-0088', '物理的な格納と内部スキーマ', 'データベースを記録媒体にどのように格納するかを記述したものはどれか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成31年度 春期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "概念スキーマ", "explanation": "データベース全体の論理的な構造を表す。"}, {"id": 2, "body": "外部スキーマ", "explanation": "特定の利用者やアプリケーションから見た論理的な構造を表す。"}, {"id": 3, "body": "サブスキーマ", "explanation": "データベースのうち特定の利用者などが使用する部分の構造を表す。"}, {"id": 4, "body": "内部スキーマ", "explanation": "記録媒体上でのデータの物理的な格納方式を表す。"}]'::jsonb, 4, '記録媒体上でのデータの物理的な格納方式を表す。', null, true),
  ('DMQ-0089', '年度別の集計とHAVING', '過去3年分の記録を保存している“試験結果”表から、2018年度の平均点数が600点以上となったクラスのクラス名と平均点数の一覧を取得するSQL文はどれか。ここで、実線の下線は主キーを表す。', 'DM-A-09-02-09', 'ipa_past', '出典：平成31年度 春期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "SELECT クラス名,AVG(点数) FROM 試験結果\nGROUP BY クラス名 HAVING AVG(点数) >= 600", "explanation": "年度の条件がないので、保存されている全期間の点数が集計対象になる。"}, {"id": 2, "body": "SELECT クラス名,AVG(点数) FROM 試験結果\nWHERE 受験年月日 BETWEEN ''2018-04-01'' AND ''2019-03-31''\nGROUP BY クラス名 HAVING AVG(点数) >= 600", "explanation": "WHEREで対象年度の行を選び、クラスごとに集計し、HAVINGで平均点を絞り込む。"}, {"id": 3, "body": "SELECT クラス名,AVG(点数) FROM 試験結果\nWHERE 受験年月日 BETWEEN ''2018-04-01'' AND ''2019-03-31''\nGROUP BY クラス名 HAVING 点数 >= 600", "explanation": "HAVINGの条件がクラスの平均点ではなく、個々の点数を参照している。"}, {"id": 4, "body": "SELECT クラス名,AVG(点数) FROM 試験結果\nWHERE 点数 >= 600\nGROUP BY クラス名\nHAVING (MAX(受験年月日)\nBETWEEN ''2018-04-01'' AND ''2019-03-31'')", "explanation": "600点未満の行を平均の計算前に除外するため、クラスの平均点を正しく求められない。"}]'::jsonb, 2, 'WHEREで対象年度の行を選び、クラスごとに集計し、HAVINGで平均点を絞り込む。', 'ipa-original/DMQ-0089.png', true),
  ('DMQ-0090', 'ACID特性の一貫性', 'トランザクションのACID特性のうち、一貫性（consistency）の説明はどれか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成31年度 春期 応用情報技術者試験 午前 問30（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "整合性の取れたデータベースに対して、トランザクション実行後も整合性が取れている性質である。", "explanation": "更新を行ってもデータの整合性制約が保たれることが一貫性である。"}, {"id": 2, "body": "同時実行される複数のトランザクションは互いに干渉しないという性質である。", "explanation": "同時実行処理の影響を分離する独立性の説明である。"}, {"id": 3, "body": "トランザクションは、完全に実行が完了するか、全く実行されなかったかの状態しかとらない性質である。", "explanation": "全て実行するか全て取り消すかを保証する原子性の説明である。"}, {"id": 4, "body": "ひとたびコミットすれば、その後どのような障害が起こっても状態の変更が保たれるという性質である。", "explanation": "確定した変更が保持される永続性の説明である。"}]'::jsonb, 1, '更新を行ってもデータの整合性制約が保たれることが一貫性である。', null, true),
  ('DMQ-0091', '製品データの一元管理', 'PDM（Product Data Management）の目的はどれか。', 'DM-A-08-01-02', 'ipa_past', '出典：平成31年度 春期 応用情報技術者試験 午前 問72（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "NC工作機械、自動搬送装置、倉庫などを有機的に結合し、コンピュータで集中管理することによって、多品種少量生産に対応できる生産の自動化を実現する。", "explanation": "工作機械や搬送設備を統合して生産を自動化する仕組みである。"}, {"id": 2, "body": "図面・部品構成データ、仕様書データなどの設計及び開発の段階で発生する情報を一元管理することによって、設計業務及び開発業務の効率を向上させる。", "explanation": "製品に関する設計・開発データを一元管理し、業務で共有・活用できるようにする。"}, {"id": 3, "body": "製品の生産計画に基づいてその生産に必要な資材の所要量を展開し、これを基準にして資材の需要とその発注時期を算出する。", "explanation": "資材の必要量や時期を求める資材所要量計画の説明である。"}, {"id": 4, "body": "部品の供給から製品の販売までの一連のプロセスの情報をリアルタイムで交換することによって、在庫の削減とリードタイムの短縮を実現する。", "explanation": "供給から販売までを横断して管理するサプライチェーン管理の説明である。"}]'::jsonb, 2, '製品に関する設計・開発データを一元管理し、業務で共有・活用できるようにする。', null, true),
  ('DMQ-0092', '保守記録の集計単位', '設備ごとの故障傾向を分析する。設備台帳では設備IDは交換まで変わらず、同じ型式の設備が複数ある。設置場所が移ると設備名は変更される。故障記録の集計用として適切なキーはどれか。', 'DM-A-08-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "設備IDで点検と故障の各記録を結び付ける。", "explanation": "名前や場所が変わっても、同じ設備の履歴を追える。"}, {"id": 2, "body": "設備名で点検と故障の各記録を結び付ける。", "explanation": "名前の変更前後で同じ設備の履歴が分かれる。"}, {"id": 3, "body": "型式で点検と故障の各記録を結び付ける。", "explanation": "同じ型式の複数設備が一つにまとめられる。"}, {"id": 4, "body": "設置場所で点検と故障の各記録を結び付ける。", "explanation": "移動前後で履歴が分かれ、同じ場所の別設備も混ざり得る。"}]'::jsonb, 1, '名前や場所が変わっても、同じ設備の履歴を追える。', null, true),
  ('DMQ-0093', '購買履歴のライフサイクル設計', '会員サービスで購買履歴を集計するため、業務部門が分析用に購買履歴を複製する。社内規程では、収集する項目を利用目的に必要なものに限り、保管期限を迎えたデータは複製も含めて廃棄することとしている。この規程を満たす設計はどれか。', 'DM-A-08-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "必要な項目だけを収集し、原本と複製の保管先・管理責任を登録して、期限に従い両方を廃棄する。", "explanation": "収集する項目を必要なものに絞っている。さらに、原本と複製の保管先と管理責任を記録し、保管期限に両方を廃棄する手順がある。"}, {"id": 2, "body": "将来利用する可能性がある項目も収集し、原本と複製の保管先を登録して、期限に従い両方を廃棄する。", "explanation": "原本と複製は期限どおりに廃棄できる。一方、将来使うかもしれないという理由で項目を増やすと、現在の利用目的に必要な収集範囲を超える。"}, {"id": 3, "body": "必要な項目だけを収集して原本を期限どおりに廃棄し、業務部門に渡した複製は集計用として保管を続ける。", "explanation": "業務部門に渡した分析用の複製にも保管期限が適用される。原本を廃棄しても、その複製が残る。"}, {"id": 4, "body": "必要な項目だけを収集して原本と複製の管理責任を登録し、期限になったデータは参照権を外して保管を続ける。", "explanation": "参照権を外すと閲覧は制限されるが、保存したデータは残る。保管期限を迎えた原本と複製には廃棄が必要である。"}]'::jsonb, 1, '収集時には、各項目が利用目的に必要かを確認する。保管期限を迎えたときには、原本に加え、業務部門が分析用に作った複製も廃棄する。', null, true),
  ('DMQ-0094', 'データオーナーとスチュワードの役割', '商品マスターで重複が増えた。データオーナーが業務上の品質基準に責任を持ち、データスチュワードが日常の品質管理を行う体制とした。a〜cのうち、データオーナーの責務だけを全て挙げたものはどれか。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0102', 'UMLの多重度と注文の対応', 'データモデルを解釈してオブジェクト図を作成した。解釈の誤りを適切に指摘した記述はどれか。ここで、モデルの表記にはUMLを用い、オブジェクト図の一部の属性の表示は省略した。', 'DM-A-17-02-02', 'ipa_past', '出典：平成29年度 春期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "“123456：注文”が複数の商品にリンクしているのは、誤りである。", "explanation": "モデルでは一つの注文に対応する商品は一つである。注文123456には二つの商品へのリンクがあるため、多重度に反する。"}, {"id": 2, "body": "“2ドア冷蔵庫：商品”が複数の注文にリンクしているのは、誤りである。", "explanation": "一つの商品に複数の注文が対応してよい。"}, {"id": 3, "body": "“A商店：顧客”が複数の注文にリンクしているのは、誤りである。", "explanation": "一人の顧客に複数の注文が対応してよい。"}, {"id": 4, "body": "“ドラム式洗濯機：商品”がどの注文にもリンクしていないのは、誤りである。", "explanation": "商品に対応する注文の多重度は「*」なので、注文が0件でもよい。"}]'::jsonb, 1, 'モデルでは一つの注文に対応する商品は一つである。注文123456には二つの商品へのリンクがあるため、多重度に反する。', 'ipa-original/DMQ-0102.png', true),
  ('DMQ-0103', '受注明細の正規形', '“受注明細”表は、どのレベルまでの正規形の条件を満足しているか。ここで、実線の下線は主キーを表す。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 春期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "第1正規形", "explanation": "各セルは単一の値を持ち、主キーの一部にだけ従属する非キー属性もないため、第2正規形まで満たす。"}, {"id": 2, "body": "第2正規形", "explanation": "商品名は商品コードによって決まり、商品コードは受注番号と明細番号の組によって決まる。部分従属はなく第2正規形を満たすが、商品名の推移的従属が残る。"}, {"id": 3, "body": "第3正規形", "explanation": "商品名が商品コードを介して主キーに推移的に従属している。"}, {"id": 4, "body": "第4正規形", "explanation": "第3正規形を満たさないため、第4正規形にも該当しない。"}]'::jsonb, 2, '商品名は商品コードによって決まり、商品コードは受注番号と明細番号の組によって決まる。部分従属はなく第2正規形を満たすが、商品名の推移的従属が残る。', 'ipa-original/DMQ-0103.png', true),
  ('DMQ-0104', 'テーブル更新のデッドロック', 'トランザクションAとBが、共通の資源であるテーブルaとbを表に示すように更新するとき、デッドロックとなるのはどの時点か。ここで、表中の①～⑧は処理の実行順序を示す。また、ロックはテーブルの更新直前にテーブル単位で行い、アンロックはトランザクション終了時に行うものとする。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 春期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "③", "explanation": "Aがテーブルaをロックできるので、待ちが発生しない。"}, {"id": 2, "body": "④", "explanation": "Bがテーブルbをロックできるので、待ちが発生しない。"}, {"id": 3, "body": "⑤", "explanation": "AがBのロック解除を待つが、この時点でBはAを待っていない。"}, {"id": 4, "body": "⑥", "explanation": "AはBが保持するbを待ち、BはAが保持するaを待つ。互いの処理が進められない循環待ちが成立する。"}]'::jsonb, 4, 'AはBが保持するbを待ち、BはAが保持するaを待つ。互いの処理が進められない循環待ちが成立する。', 'ipa-original/DMQ-0104.png', true),
  ('DMQ-0105', 'ストアドプロシージャと通信量', 'ストアドプロシージャの利点はどれか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問26（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "アプリケーションプログラムからネットワークを介してDBMSにアクセスする場合、両者間の通信量を減少させる。", "explanation": "複数のSQL文や途中結果を毎回送受信する代わりに、DBMS側で処理をまとめて実行し、必要な結果を返せる。"}, {"id": 2, "body": "アプリケーションプログラムからの一連の要求を一括して処理することによって、DBMS内の実行計画の数を減少させる。", "explanation": "プロシージャにまとめても内部のSQLには実行計画が必要であり、計画の数が減る保証はない。"}, {"id": 3, "body": "アプリケーションプログラムからの一連の要求を一括して処理することによって、DBMS内の必要バッファ数を減少させる。", "explanation": "バッファ量は処理内容やデータ量に左右される。"}, {"id": 4, "body": "データが格納されているディスク装置へのI/O回数を減少させる。", "explanation": "プロシージャを使っても、必要なデータを読み書きする処理は残る。"}]'::jsonb, 1, '複数のSQL文や途中結果を毎回送受信する代わりに、DBMS側で処理をまとめて実行し、必要な結果を返せる。', null, true),
  ('DMQ-0106', '第3正規形の効果', '第3正規形であることの効果又は影響に関する記述として、適切なものはどれか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "画面や帳票の行をそのままデータベースの行に対応させるので、データ量が増える。", "explanation": "表は属性の従属関係を基に設計するため、画面や帳票の行構成に合わせる必要はない。"}, {"id": 2, "body": "結合操作が不要となり、データベース全体の処理効率が向上する。", "explanation": "正規化によって表を分けると、必要な情報を取り出すために結合が増えることがある。"}, {"id": 3, "body": "更新時のデッドロックを避けることができる。", "explanation": "デッドロックを抑えるには、ロックの取得順序など同時実行制御を考える必要がある。"}, {"id": 4, "body": "冗長性が排除され、データの整合性を保ちやすくなる。", "explanation": "非キー属性間の推移的な従属関係を解消すると、同じ事実を複数箇所で更新して生じる不整合を抑えられる。"}]'::jsonb, 4, '非キー属性間の推移的な従属関係を解消すると、同じ事実を複数箇所で更新して生じる不整合を抑えられる。', null, true),
  ('DMQ-0107', '射影とSELECT DISTINCT', '関係R（ID, A, B, C）のA, Cへの射影の結果とSQL文で求めた結果が同じになるように、aに入れるべき字句はどれか。ここで、関係Rを表Tで実現し、表Tに各行を格納したものを次に示す。', 'DM-A-09-02-09', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問28（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "ALL", "explanation": "ALLは同じ値の組が複数行にあれば、それらを全て返す。"}, {"id": 2, "body": "DISTINCT", "explanation": "射影の結果は集合なので同じ値の組を1件にまとめる。DISTINCTを指定すると、AとCの組が同じ行が1件になる。"}, {"id": 3, "body": "ORDER BY", "explanation": "ORDER BYは並べ替えに使い、重複は除去しない。"}, {"id": 4, "body": "REFERENCES", "explanation": "REFERENCESは外部キーの参照先を指定するために使う。"}]'::jsonb, 2, '射影の結果は集合なので同じ値の組を1件にまとめる。DISTINCTを指定すると、AとCの組が同じ行が1件になる。', 'ipa-original/DMQ-0107.png', true),
  ('DMQ-0108', '待ちグラフでの永久待ち', 'トランザクションA～Gの待ちグラフにおいて、永久待ちの状態になっているトランザクション全てを列挙したものはどれか。ここで、待ちグラフのX→Yは、トランザクションXはトランザクションYがロックしている資源のアンロックを待っていることを表す。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問29（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "A, B, C, D", "explanation": "Aに待ち先はなく、永久待ちにならない。永久待ちになるFも含まれていない。"}, {"id": 2, "body": "B, C, D", "explanation": "循環を構成する三つは含まれるが、その循環に含まれるDを待つFが抜けている。"}, {"id": 3, "body": "B, C, D, F", "explanation": "B→D→C→Bが循環を作る。Fは循環の一部ではないが、循環内のDを待つため永久待ちになる。"}, {"id": 4, "body": "C, D, E, F, G", "explanation": "循環内のBが抜けている。Eの待ち先であるGは他の処理を待たないので、EとGは永久待ちにならない。"}]'::jsonb, 3, 'B→D→C→Bが循環を作る。Fは循環の一部ではないが、循環内のDを待つため永久待ちになる。', 'ipa-original/DMQ-0108.png', true),
  ('DMQ-0109', 'データマイニングと関連技術', 'データマイニングの説明として、最も適切なものはどれか。', 'DM-A-09-02-10', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問30（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "基幹業務のデータベースとは別に作成され、更新処理をしない集計データの分析を主目的とする。", "explanation": "分析用のデータウェアハウスの使い方である。"}, {"id": 2, "body": "個人別データ、部門別データ、サマリデータなど、分析の目的別に切り出され、カスタマイズされたデータを分析する。", "explanation": "目的に合わせてデータマートを用意する処理である。"}, {"id": 3, "body": "スライシング、ダイシング、ドリルダウンなどのインタラクティブな操作によって多次元分析を行い、意思決定を支援する。", "explanation": "スライシングやドリルダウンを行うOLAPの説明である。"}, {"id": 4, "body": "ニューラルネットワークや統計解析などの手法を使って、大量に蓄積されているデータから、特徴あるパターンを探し出す。", "explanation": "大量の蓄積データに含まれる規則性や関連を探し出すことが、データマイニングの目的である。"}]'::jsonb, 4, '大量の蓄積データに含まれる規則性や関連を探し出すことが、データマイニングの目的である。', null, true)
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0110', '関数従属と第3正規形', '関数従属を次のように表記するとき、属性a～eで構成される関係を第3正規形にしたものはどれか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成28年度 春期 応用情報技術者試験 午前 問27（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "(a, b, c, d)　(b, d, e)", "explanation": "最初の関係にb→cが残り、cはキーaに推移的に従属する。"}, {"id": 2, "body": "(a, b, c, d)　(b, c)　(b, d, e)", "explanation": "(b,c)を追加しても、(a,b,c,d)の推移的従属は解消されない。"}, {"id": 3, "body": "(a, b, d)　(b, d, c, e)", "explanation": "後者ではキー(b,d)の一部であるbだけでcが決まる。"}, {"id": 4, "body": "(a, b, d)　(b, c)　(b, d, e)", "explanation": "b→cと(b,d)→eをそれぞれ独立した関係にし、aで決まるb、dを最初の関係に保持する。"}]'::jsonb, 4, 'b→cと(b,d)→eをそれぞれ独立した関係にし、aで決まるb、dを最初の関係に保持する。', 'ipa-original/DMQ-0110.png', true),
  ('DMQ-0111', '排他ロックの取得順序', 'トランザクションA（処理A1→処理A2の順に実行する）とトランザクションB（処理B1→処理B2の順に実行する）が、データベースの資源SとTに対し、次のように処理A1→処理B1→処理A2→処理B2の順で専有ロックを要求する場合、デッドロックが発生する資源の組合せはどれか。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0120', '相関と回帰から言えること', 'ある店舗の6月の日別最高気温と飲料販売数の相関係数は0.82だった。気温を説明変数とする単回帰式の傾きは12本/℃であった。販促の有無は記録していない。この結果の解釈として適切なものはどれか。', 'DM-A-09-02-05', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "相関係数0.82から、気温が販売数の変動の82％を説明すると解釈できる。", "explanation": "相関係数は説明できる変動の割合をそのまま表す値ではない。切片を含む単回帰では説明割合を表す決定係数は相関係数の二乗である。"}, {"id": 2, "body": "式では気温が1℃高いと予測値が12本増えるが、その差を気温だけの効果とは断定できない。", "explanation": "傾きは同じ回帰式で予測した値の差である。販促などと気温の影響を切り分けておらず、気温の因果効果までは判断できない。"}, {"id": 3, "body": "販促を説明変数から外したので、傾きは販促の影響を除いた気温の効果を表す。", "explanation": "記録やモデルに含めないことは、販促の影響を除去することとは異なる。"}, {"id": 4, "body": "日別の記録から求めた傾きなので、翌日の実測販売数は気温が1℃高くなるごとに12本増える。", "explanation": "傾きはモデル上の予測値の差であり、翌日の個々の実測値を保証しない。"}]'::jsonb, 2, '傾きは同じ回帰式で予測した値の差である。販促などと気温の影響を切り分けておらず、気温の因果効果までは判断できない。', null, true),
  ('DMQ-0121', 'AIの透明性を高める対応', '自治体が、窓口の予約に関する問合せへの回答案を作るAIを導入する。「人間中心のAI社会原則」のうち、透明性に直接対応する取組はどれか。', 'DM-A-10-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "回答を作れないときは職員が対応する手順を定め、定期的に訓練する。", "explanation": "回答不能時の安全な運用やサービスの継続につながる取組である。"}, {"id": 2, "body": "職員向けの研修を行い、回答案を確認するための知識を身に付けてもらう。", "explanation": "研修は職員のリテラシー向上に当たる。"}, {"id": 3, "body": "AIの利用箇所と回答が参照する情報を、利用者が確認しやすい場所に示す。", "explanation": "利用者がAIの関与と回答の根拠を把握できるようにすることは、透明性に直接対応する。"}, {"id": 4, "body": "利用者の連絡先は予約処理に必要な項目だけを取得し、保存期間を設定する。", "explanation": "収集量と保存期間を抑える施策は、主にプライバシーの保護に当たる。"}]'::jsonb, 3, '利用者がAIの関与と回答の根拠を把握できるようにすることは、透明性に直接対応する。', null, true),
  ('DMQ-0122', 'AIエージェントの実行前制御', 'AIエージェントが返品申請を判定する。社内規程では返金額が3万円を超える場合、又は返品理由を特定できない場合に担当者の承認が必要である。返金APIを使う際のガードレールとして、適切なものはどれか。', 'DM-A-10-04-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "返金処理側が金額と理由を照合し、該当時は承認済みの申請だけを実行する。", "explanation": "どちらか一方の条件に該当すれば、実行前に承認の有無を返金処理側で強制できる。"}, {"id": 2, "body": "エージェントに承認条件を指示し、判断の理由を実行ログに記録させる。", "explanation": "指示と記録には意味があるが、条件を見落としたときに返金APIで実行を止められない。"}, {"id": 3, "body": "金額の上限を返金APIで強制し、返品理由が不明な場合は担当者に事後通知する。", "explanation": "理由が不明な場合にも事前承認が必要であり、事後通知では満たさない。"}, {"id": 4, "body": "金額と理由の両方に問題がある場合だけ承認を待つよう、返金処理側に設定する。", "explanation": "規程の条件はORなので、どちらか一方だけに該当する申請も承認が必要である。"}]'::jsonb, 1, 'どちらか一方の条件に該当すれば、実行前に承認の有無を返金処理側で強制できる。', null, true),
  ('DMQ-0123', '社内規程と分析用データの管理', '社内規程では、取引明細から個人名を除いても、社内にある対応表で本人に戻せる間は「機密」とする。機密データは承認済み領域で保管し、担当者に利用目的ごとの権限を付与する。分析終了後、分析用の複製は削除する。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0127', 'データウェアハウス投入前のデータ整備', '業務系のデータベースから抽出したデータをデータウェアハウスに格納するために、整合されたデータ属性やコード体系などに合うように変換及び修正を行う処理はどれか。', 'DM-A-08-04-02', 'ipa_past', '出典：平成27年度 春期 データベーススペシャリスト試験 午前Ⅱ 問19（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "クラスタリング", "explanation": "データの特徴に応じてグループ分けする手法である。"}, {"id": 2, "body": "スライシング", "explanation": "多次元データから、ある分析軸について特定の値に固定した断面を取り出す操作である。"}, {"id": 3, "body": "ダイシング", "explanation": "多次元データに条件を設定し、分析対象となる部分を取り出す操作である。"}, {"id": 4, "body": "データクレンジング", "explanation": "表記やコード、形式の不一致などを整えて、統合後のデータを一貫して扱えるようにする。"}]'::jsonb, 4, '表記やコード、形式の不一致などを整えて、統合後のデータを一貫して扱えるようにする。', null, true),
  ('DMQ-0128', '秘密管理性を確認する監査', '経済産業省の“営業秘密管理指針”に基づく営業秘密データの管理状況について監査を行うとき、秘密管理性のチェックポイントはどれか。', 'DM-A-28-01-02', 'ipa_past', '出典：平成26年度 春期 システム監査技術者試験 午前Ⅱ 問4（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "当該データが経営効率の改善に役立っているかどうかを分析していること", "explanation": "データの業務上の有用性に関する観点である。"}, {"id": 2, "body": "当該データの記録媒体に秘密を意味する表示をしていること", "explanation": "表示は、データに接する人が秘密として管理されていることを認識できるようにする措置である。"}, {"id": 3, "body": "当該データの内容が刊行物に掲載されていないかを定期的に確認していること", "explanation": "公に知られていないかの確認は、非公知性に関する観点である。"}, {"id": 4, "body": "当該データの内容が公序良俗に反していないかを確認していること", "explanation": "公序良俗に関する確認では、組織がそのデータを秘密として扱っているかは分からない。"}]'::jsonb, 2, '表示は、データに接する人が秘密として管理されていることを認識できるようにする措置である。', null, true),
  ('DMQ-0129', '情報セキュリティ基本方針の役割', 'ISMSにおいて定義することが求められている情報セキュリティ基本方針に関する記述のうち、適切なものはどれか。', 'DM-A-24-02-01', 'ipa_past', '出典：平成25年度 秋期 高度試験共通 午前Ⅰ 問14（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "重要な基本方針を定めた機密文書であり、社内の関係者以外の目に触れないようにする。", "explanation": "基本方針は、組織内に周知し、必要に応じて関係する利害関係者も参照できるようにする。"}, {"id": 2, "body": "情報セキュリティの基本方針を述べたものであり、ビジネス環境や技術が変化しても変更してはならない。", "explanation": "事業環境やリスクが変われば、基本方針も見直す。"}, {"id": 3, "body": "情報セキュリティのための経営陣の方向性及び支持を規定する。", "explanation": "基本方針は、経営陣が組織として何を目指し、情報セキュリティをどう支えるかを示す。"}, {"id": 4, "body": "特定のシステムについてリスク分析を行い、そのセキュリティ対策とシステム運用の詳細を記述する。", "explanation": "個別システムの対策や手順は、組織の基本方針を具体化する文書で扱う。"}]'::jsonb, 3, '基本方針は、経営陣が組織として何を目指し、情報セキュリティをどう支えるかを示す。', null, true),
  ('DMQ-0130', '制約と目的から選ぶ最適化手法', '“1次式で表現される制約条件の下にある資源を、どのように配分したら1次式で表される効果の最大が得られるか”という問題を解く手法はどれか。', 'DM-A-09-03-02', 'ipa_past', '出典：平成24年度 春期 応用情報技術者試験 午前 問76（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "因子分析法", "explanation": "複数の観測変数に共通する潜在的な因子を調べる手法である。"}, {"id": 2, "body": "回帰分析法", "explanation": "変数の関係をモデル化し、目的変数の説明や予測に用いる。"}, {"id": 3, "body": "実験計画法", "explanation": "実験の条件を計画し、要因やその組合せの効果を評価する。"}, {"id": 4, "body": "線形計画法", "explanation": "一次式で表される制約の下で、一次式で表される目的を最大化または最小化する。"}]'::jsonb, 4, '一次式で表される制約の下で、一次式で表される目的を最大化または最小化する。', null, true),
  ('DMQ-0131', '相関係数が示す関係', '相関係数に関する記述のうち、適切なものはどれか。', 'DM-A-09-02-05', 'ipa_past', '出典：平成23年度 特別 高度試験共通 午前Ⅰ 問1（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "すべての標本点が正の傾きをもつ直線上にあるときは、相関係数が＋1になる。", "explanation": "変量が完全に正の線形関係にあると、相関係数は＋1になる。"}, {"id": 2, "body": "変量間の関係が線形のときは、相関係数が0になる。", "explanation": "点が直線上に並ぶ場合、傾きの向きに応じて相関係数は＋1または−1となる。"}, {"id": 3, "body": "変量間の関係が非線形のときは、相関係数が負になる。", "explanation": "非線形であることから符号は決まらない。相関係数は線形な関係の強さと向きを測る値である。"}, {"id": 4, "body": "無相関のときは、相関係数が－1になる。", "explanation": "無相関の場合は0である。−1は完全な負の線形関係を表す。"}]'::jsonb, 1, '変量が完全に正の線形関係にあると、相関係数は＋1になる。', null, true),
  ('DMQ-0132', 'Apacheを改変して頒布するときの表示', 'Webサーバ用のソフトウェアであるApacheを変更して、新しい製品を作って頒布するとき、実行しなければならないものはどれか。', 'DM-A-28-01-04', 'ipa_past', '出典：平成22年度 春期 応用情報技術者試験 午前 問22（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "Apacheの名称を製品名に使う。", "explanation": "製品名にApacheを使う義務はない。名称や商標の使用にはライセンス上の制約がある。"}, {"id": 2, "body": "変更したファイルに自社の著作権表示を追加する。", "explanation": "自社の著作権表示は付けられる場合があるが、追加自体は必須ではない。"}, {"id": 3, "body": "変更したファイルには変更した旨の告知を入れる。", "explanation": "Apache License 2.0の第4条は、変更したファイルに変更を示す明瞭な告知を求める。"}, {"id": 4, "body": "ライセンス文を改変し、添付する。", "explanation": "ライセンスの写しを頒布先に渡す必要がある。原ライセンス文を改変する義務はない。"}]'::jsonb, 3, 'Apache License 2.0の第4条は、変更したファイルに変更を示す明瞭な告知を求める。', null, true),
  ('DMQ-0133', '退職者のアクセス権削除の確認', 'アクセス権限を管理しているシステムの利用者IDリストから、退職による権限喪失者が削除されていることを検証する手続として、最も適切なものはどれか。', 'DM-A-24-02-02', 'ipa_past', '出典：平成21年度 春期 システム監査技術者試験 午前Ⅱ 問1（句読点を統一。解説は独自作成）', '[{"id": 1, "body": "アクセス権限削除申請書の全件について、利用者IDリストから削除されていることを確認する。", "explanation": "申請が漏れている退職者は、申請書を起点にすると見つけられない。"}, {"id": 2, "body": "最新の利用者IDリストの全件について、対応するアクセス権限削除申請書が存在しないことを確認する。", "explanation": "申請が出ていなければ、一覧に残っている退職者も確認を通過してしまう。"}, {"id": 3, "body": "人事発令簿の退職者の全件について、利用者IDリストから削除されていることを確認する。", "explanation": "削除が必要な人を人事記録で把握すると、申請や削除処理の漏れも確認できる。"}, {"id": 4, "body": "利用者IDリストの更新履歴の全件について、対応するアクセス権限削除申請書の存在を確認する。", "explanation": "更新記録を起点にすると、削除処理が行われず履歴に現れない退職者は検証できない。"}]'::jsonb, 3, '削除が必要な人を人事記録で把握すると、申請や削除処理の漏れも確認できる。', null, true)
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0134', 'AIを使う担当者への教育', '問い合わせ窓口で、担当者が生成AIの回答案を確認してから顧客に送る。誤った回答案を見分けるため、典型的な誤りと確認方法を担当者が演習で学ぶ。この取組に最も直接対応するAI社会原則はどれか。', 'DM-A-10-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "プライバシー確保の原則", "explanation": "個人情報の取得や利用を適切に管理する原則である。この演習の目的は、回答案を検証する力を養うことである。"}, {"id": 2, "body": "教育・リテラシーの原則", "explanation": "AIの限界を理解し、出力を検証して使う能力を、担当者が演習で身に付ける取組である。"}, {"id": 3, "body": "公正競争確保の原則", "explanation": "主に市場で公正な競争が行われる環境に関する原則であり、担当者の技能を養う取組とは目的が異なる。"}, {"id": 4, "body": "イノベーションの原則", "explanation": "新たな価値を生むための連携や技術の発展に関する原則である。この取組で直接育てるのは利用者のリテラシーである。"}]'::jsonb, 2, 'AIの限界を理解し、出力を検証して使う能力を、担当者が演習で身に付ける取組である。', null, true),
  ('DMQ-0135', '在庫照会エージェントの権限', '在庫照会用のAIエージェントには、在庫数の取得だけが必要である。在庫システムには照会と更新のAPIがある。最小権限に沿う設定はどれか。', 'DM-A-10-04-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "照会・更新の権限を持つ専用アカウントを発行し、操作ログを個別に記録する。", "explanation": "専用アカウントは追跡に役立つが、処理に不要な更新権限が残る。"}, {"id": 2, "body": "照会・更新の権限を保ったまま、画面から更新操作を選べないようにする。", "explanation": "画面の制限は誤操作を減らせるが、認証情報に付与したAPIの権限は変わらない。"}, {"id": 3, "body": "照会・更新の権限を期限付きで発行し、短時間で失効するように設定する。", "explanation": "有効期限を短くしても、有効な間に許される操作は照会に限定されない。"}, {"id": 4, "body": "照会APIだけを許可した専用アカウントを発行する。", "explanation": "必要な機能に権限を限定する。操作ログや有効期限は別の管理手段であり、権限の範囲を絞る代わりにはならない。"}]'::jsonb, 4, '必要な機能に権限を限定する。操作ログや有効期限は別の管理手段であり、権限の範囲を絞る代わりにはならない。', null, true),
  ('DMQ-0136', '未測定の値を実測値として記録', '品質検査の担当者は、ある製品を今月は測定していなかったため、前月の実測値を基に今月の値を推定した。担当者はその値を、今月の検査報告書の「実測値」欄に記入した。この記入はどの行為に当たるか。', 'DM-A-27-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "データのねつ造", "explanation": "前月の実測値を基に推定しても、今月の測定結果が得られたことにはならない。得られていない今月の測定結果を実測値として記録したため、データのねつ造に当たる。"}, {"id": 2, "body": "データの改ざん", "explanation": "改ざんは、既に存在する記録を不正に変更する行為である。この事例では前月の記録を書き換えたのではなく、測定していない今月の値を実測値として記録している。"}, {"id": 3, "body": "データの盗用", "explanation": "盗用は、他者のデータを自分が得たもののように扱う行為である。この事例の問題は、前月の記録を推定に用いたことではなく、今月の推定値を実測値として記録したことである。"}, {"id": 4, "body": "データの補完", "explanation": "欠損値の補完が認められる場合は、推定値を実測値と区別し、補完の方法を記録する。実測値が求められる検査では、推定値と明示しても実測の代わりにはできない。"}]'::jsonb, 1, '前月の実測値を基に推定しても、今月の測定結果が得られたことにはならない。得られていない今月の測定結果を実測値として記録したため、データのねつ造に当たる。', null, true),
  ('DMQ-0137', '一貫性の問題から正確性を確認する', '顧客台帳と配送システムに同じ顧客の住所があるが、町名が一致しない。どちらも入力形式は正しく、配送システムの更新日時が新しい。どの住所が正確かを判定する方法として、適切なものはどれか。', 'DM-A-08-04-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "更新日時が新しい配送システムの住所を正しいと判定する。", "explanation": "更新日時から分かるのはレコードが更新された時点であり、住所が正しいことまでは確認できない。"}, {"id": 2, "body": "住所欄を空欄にせず入力しているので、どちらも正しいと判定する。", "explanation": "空欄でないことは完全性に関する確認であり、実際の住所を表しているかは別に確認する必要がある。"}, {"id": 3, "body": "本人が届け出た最新の住所と照合し、差があるレコードを特定する。", "explanation": "確認済みの届出という根拠を使い、業務で使う住所として正確な値を判定できる。"}, {"id": 4, "body": "顧客台帳の住所で両方を統一し、正確になったと判定する。", "explanation": "一致するよう変更しても、統一した値が事実に合うかを確認していない。"}]'::jsonb, 3, '確認済みの届出という根拠を使い、業務で使う住所として正確な値を判定できる。', null, true),
  ('DMQ-0138', 'カタログで指標の定義を確認する', '他部署のデータカタログで、同じ名称の「有効会員数」が複数見つかった。月次資料で使う指標を選ぶ前に、休会中の会員が含まれるかを確かめたい。カタログで最初に確認する情報はどれか。', 'DM-A-08-05-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "会員状態コードのデータ型と入力可能な値", "explanation": "どんな状態を記録できるかは分かるが、集計でどの状態を数えるかは分からない。"}, {"id": 2, "body": "指標の業務定義に記載された集計対象と除外条件", "explanation": "同名の指標でも対象や除外条件が異なることがある。休会中の会員の扱いは、指標ごとの業務定義で確認する。"}, {"id": 3, "body": "指標の集計頻度と最終更新日時", "explanation": "更新頻度や鮮度は分かるが、休会中の会員を数えるかは分からない。"}, {"id": 4, "body": "指標の来歴に記録された入力テーブルと更新経路", "explanation": "来歴は生成元や処理を追うときに役立つが、入力元と更新経路だけでは休会を除外する条件を確認できない。"}]'::jsonb, 2, '同名の指標でも対象や除外条件が異なることがある。休会中の会員の扱いは、指標ごとの業務定義で確認する。', null, true),
  ('DMQ-0139', '部門をまたぐ品質課題の報告', '販売部のデータスチュワードが、販売部と物流部で同じ商品コードが異なる商品に割り当てられ、全社集計で別の商品が合算されていることを発見した。この会社では、全社で使うコード体系を変更する際には、関係部門への影響を確認することになっている。発見したデータスチュワードが最初に行う対応として、最も適切なものはどれか。', 'DM-A-08-03-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "販売部で使っているコードの根拠を確認し、物流部のデータスチュワードに割当ての変更を依頼する。", "explanation": "販売部の割当ての根拠を調べても、どちらのコードを残すかは判断できない。他部門での利用や既存データへの影響を踏まえて変更を決める必要がある。"}, {"id": 2, "body": "物流部のデータスチュワードと影響範囲を確認し、両者で全社共通のコードと切替日を決める。", "explanation": "同じ立場の担当者と事実を確認することには意味がある。共通コードと切替日の決定には、部門のデータに責任を持つデータオーナーと、部門間の調整を担うDMOの関与が必要である。"}, {"id": 3, "body": "販売部の集計用に対応表を作成して次回の月次報告に適用し、その結果を見て全社対応を検討する。", "explanation": "部門内での対応表は暫定措置になり得るが、全社集計では既に別の商品が合算されている。次回報告まで待つと、影響を受ける部門と責任者に問題が共有されない。"}, {"id": 4, "body": "不一致の例と判明している影響を整理し、販売部のデータオーナーに報告する。", "explanation": "データスチュワードは日常のデータ品質を管理し、不一致を調査して影響を報告する。データオーナーは担当データに関する意思決定に責任を持つ。DMO（データマネジメントオフィス）は、影響を受ける部門のデータオーナー間の調整を支援する。"}]'::jsonb, 4, 'データスチュワードは日常のデータ品質を管理し、不一致を調査して影響を報告する。データオーナーは担当データに関する意思決定に責任を持つ。DMO（データマネジメントオフィス）は、影響を受ける部門のデータオーナー間の調整を支援する。', null, true),
  ('DMQ-0140', '平均が等しいときのばらつき', '二つの倉庫の同じ期間の出荷所要時間を比較した。平均はどちらも40分で、標準偏差は倉庫Aが5分、倉庫Bが20分であった。所要時間の安定性を改善するため、この情報から判断できることはどれか。', 'DM-A-09-02-04', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "倉庫Bの所要時間のばらつきが大きく、時間帯や作業区分ごとに変動要因を調べる価値がある。", "explanation": "単位と比較期間が同じなので、標準偏差が大きい倉庫Bは平均の周りのばらつきが大きい。"}, {"id": 2, "body": "平均が同じなので、両倉庫のばらつきも同程度である。", "explanation": "平均が同じでも、平均の周りへのデータの広がりは異なり得る。"}, {"id": 3, "body": "倉庫Bのばらつきが大きいのは、特定の時間帯の作業が原因である。", "explanation": "標準偏差から変動の大きさは分かるが、時間帯などの原因は特定できない。"}, {"id": 4, "body": "倉庫Aの出荷はすべて平均の前後5分以内に収まる。", "explanation": "標準偏差は個々の観測値が収まる範囲の上限を表さない。"}]'::jsonb, 1, '単位と比較期間が同じなので、標準偏差が大きい倉庫Bは平均の周りのばらつきが大きい。', null, true),
  ('DMQ-0141', '更新される規程を参照する生成AI', '社内規程に関する問い合わせに生成AIで回答する。規程は毎月改定され、利用者が閲覧できる範囲は所属によって異なる。回答には、閲覧できる現行規程の根拠箇所を示す必要がある。閲覧できる現行規程の全文を一度に指示文へ入れることはできない。この要件を満たす構成はどれか。', 'DM-A-10-03-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "改定のたびに現行規程でモデルを追加学習し、規程番号と条番号を添えて回答させる。", "explanation": "追加学習で改定内容を反映する方法には、改定のたびに学習と検証が必要になる。学習済みの知識だけでは、示した条文が回答の根拠になっていることや、その条文を利用者が閲覧できることを確認できない。"}, {"id": 2, "body": "所属ごとに閲覧できる現行規程の全文を指示文に入れ、該当する条文を引用して回答させる。", "explanation": "許可された文書だけを指示文に渡す考え方は適切だが、ここでは閲覧できる規程の全文が指示文に収まらない。質問に関係する箇所を選んで渡す必要がある。"}, {"id": 3, "body": "所属別の閲覧条件で現行規程を検索し、該当箇所と出典を渡して回答させる。", "explanation": "RAG（検索拡張生成）は、回答時に外部文書を検索し、得られた箇所を指示文に含めて生成AIに渡す方式である。規程が改定されたら検索対象を更新すればよく、回答のためにモデルを再学習する必要はない。検索時に閲覧権限と版を絞り、取得した条文を根拠として示せる。"}, {"id": 4, "body": "現行規程を横断検索して回答させ、提示する根拠箇所が閲覧可能かを公開前に確認する。", "explanation": "根拠箇所の表示だけを確認しても、閲覧できない規程の内容をモデルが回答本文に取り込む可能性がある。モデルに検索結果を渡す前に、閲覧権限で絞る必要がある。"}]'::jsonb, 3, 'RAG（検索拡張生成）は、回答時に外部文書を検索し、得られた箇所を指示文に含めて生成AIに渡す方式である。規程が改定されたら検索対象を更新すればよく、回答のためにモデルを再学習する必要はない。検索時に閲覧権限と版を絞り、取得した条文を根拠として示せる。', null, true),
  ('DMQ-0142', '重複候補を抱えた集計の暫定対応', '営業報告の締切までに法人顧客数を集計する。同一法人と確認できた重複と、同名だが同一法人か確認できない重複候補がある。分析用の複製は編集できるが、原本を修正するのはデータオーナーである。締切時点の報告と原本への対応の組合せとして、最も適切なものはどれか。', 'DM-A-08-04-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "同名の候補を複製で統合して顧客数を報告し、統合した一覧をオーナーに渡す。", "explanation": "候補を一律に統合すると、別法人も一つに数えてしまう。"}, {"id": 2, "body": "確認済みの重複だけを複製で統合し、未確定分の扱いを記して報告し、原本の確認をオーナーに依頼する。", "explanation": "確認済みの重複を除き、未確認の候補をどう数えたかを明らかにすれば、締切時点の数値の限界を伝えられる。原本の修正は権限を持つオーナーが判断する。"}, {"id": 3, "body": "確認済みの重複だけを原本で統合し、未確定分はオーナーに調査を依頼する。", "explanation": "統合する対象は適切に絞っているが、原本を変更する権限は担当者にない。"}, {"id": 4, "body": "全レコードを別の法人として顧客数を報告し、重複の照合をオーナーに依頼する。", "explanation": "確認済みの重複まで別法人として数えるため、既に把握している過大集計を報告値に残してしまう。"}]'::jsonb, 2, '確認済みの重複を除き、未確認の候補をどう数えたかを明らかにすれば、締切時点の数値の限界を伝えられる。原本の修正は権限を持つオーナーが判断する。', null, true),
  ('DMQ-0143', '共通指標と部門指標をBIで扱う', '全社のBI報告では、返品を控除した税抜売上（純売上）を部門横断で比較している。営業部は日々の業務で、税込・返品控除前の請求額（請求額売上）をBIツール上で継続して参照する必要がある。全社指標の定義変更にはデータオーナーの承認が必要である。BIツールでの指標の定義方法として、適切なものはどれか。', 'DM-A-09-01-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "営業部が全社共通の売上を請求額売上の計算式に差し替え、全部門のダッシュボードでその定義を使う。", "explanation": "計算式を一つにそろえても、純売上で比較するという全社報告の要件を満たさない。営業部による差し替えはデータオーナーの承認手続も経ていない。"}, {"id": 2, "body": "純売上をBIの共通指標として公開し、請求額売上は営業部で明細を出力して集計する運用にする。", "explanation": "全社で純売上を比較できるが、出力後に別途集計するため、営業部が請求額売上をBIツール上で継続して参照する要件を満たさない。"}, {"id": 3, "body": "指標名を「売上」に統一し、営業部には請求額売上、ほかの部門には純売上を同じ指標名で表示する。", "explanation": "同じ指標名の値が閲覧部門によって異なる定義で計算される。部門同士でその値を比較したり、同じ指標名で報告結果を再現したりできない。"}, {"id": 4, "body": "純売上と請求額売上を別名で登録し、全社報告では承認済みの純売上の定義を使う。", "explanation": "セマンティックレイヤーは、BIで使う指標名や計算式などの定義を一元管理する層である。純売上と請求額売上を別名で登録すると、利用者は用途に応じて計算条件を確認できる。全社報告には承認済みの純売上を適用し、定義の変更はデータオーナーの承認を経る。"}]'::jsonb, 4, 'セマンティックレイヤーは、BIで使う指標名や計算式などの定義を一元管理する層である。純売上と請求額売上を別名で登録すると、利用者は用途に応じて計算条件を確認できる。全社報告には承認済みの純売上を適用し、定義の変更はデータオーナーの承認を経る。', null, true)
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0144', '貸出業務の概念モデル', '備品貸出システムの設計を始める。現場の担当者と、何を管理し、それらがどのように関係するかを確認するために、最初に概念データモデルを作る。モデルに示す内容として、最も適切なものはどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "貸出履歴表の列に使うデータ型と桁数", "explanation": "列の型や桁数は、業務の対象と関係が明らかになった後に詳細化する。"}, {"id": 2, "body": "利用者、備品、貸出という対象と相互の関係", "explanation": "現場の担当者が、管理したい対象とその関係が表現されているかを確認できる。"}, {"id": 3, "body": "返却日の検索に用いる索引の種類と構成", "explanation": "索引はアクセス効率を調整する物理設計の要素である。"}, {"id": 4, "body": "利用部門に応じて表示する項目と画面の配置", "explanation": "画面の設計では利用者ごとの見せ方を扱う。業務で管理する対象の関係は別に定義する。"}]'::jsonb, 2, '概念データモデルでは、業務で管理する対象とそれらの関係を表す。この段階では、表への変換や製品ごとの実装方法は後続の設計に委ねる。', null, true),
  ('DMQ-0145', '点検の実施履歴', '各設備は、稼働前なら点検記録がなく、稼働後は繰り返し点検を受ける。点検記録1件は、必ず一つの設備について作成する。「設備1件に対する点検記録の件数」と「点検記録1件に対する設備の件数」の組合せとして、適切なものはどれか。', 'DM-A-17-02-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "0件以上 ／ 1件", "explanation": "未点検と点検の繰返しを表せる。各記録の点検対象も一つに特定できる。"}, {"id": 2, "body": "1件以上 ／ 1件", "explanation": "未点検の設備は登録できない関係になってしまう。"}, {"id": 3, "body": "0件又は1件 ／ 1件", "explanation": "同じ設備の2回目以降の点検を別の記録として登録できない。"}, {"id": 4, "body": "0件以上 ／ 1件以上", "explanation": "1件の点検記録が複数の設備を対象にできる関係になってしまう。"}]'::jsonb, 1, '未点検の設備も登録できるので、設備から見た点検記録の最小件数は0件で、複数件まで登録できる。点検記録から見た設備は必ず1件である。', null, true),
  ('DMQ-0146', '点検当時の所属拠点を集計', '点検システムは、設備表に設備IDと現在の所属拠点IDを保存し、点検表に設備ID、点検日、結果を保存している。設備の移設時には設備表の拠点IDを上書きしており、移設履歴は保存していない。今後の点検について、点検当時の所属拠点ごとに件数を再集計できるようにする。最も適切な変更はどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "設備表に、現在の所属拠点IDと最終移設日を保存する。", "explanation": "最終移設日より前の点検を見分けられても、その点検時の拠点IDは分からない。"}, {"id": 2, "body": "点検日と設備IDで点検表に索引を作り、設備表と結合する。", "explanation": "検索は効率化できるが、結合で取得できるのは現在の拠点IDである。"}, {"id": 3, "body": "点検表に、点検当時の所属拠点IDを追加して保存する。", "explanation": "点検と拠点を直接結び付けるので、移設後も点検時の拠点を特定できる。"}, {"id": 4, "body": "設備表に、現在の拠点IDに加えて一つ前の拠点IDを保存する。", "explanation": "複数回移設すると古い拠点の情報が失われ、どの点検がどの拠点に対応するかも特定できない。"}]'::jsonb, 3, '点検当時の拠点は点検という出来事の情報であり、設備の現在の拠点とは時点が異なる。点検時に拠点IDを記録しておけば、後から移設しても同じ条件で集計できる。', null, true),
  ('DMQ-0147', '未提出の店舗を含めた一覧', '店舗表には全店舗が1店舗1行で登録されている。月報表には月報を受け付けたときだけ、店舗IDと対象月を1件記録する。指定月の提出・未提出を全店舗について一覧にする方法として、適切なものはどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "指定月の月報を起点に店舗表を照合し、店舗表にない行を未提出とする。", "explanation": "未提出の店舗は指定月の月報に行がないので、一覧の起点に含まれない。"}, {"id": 2, "body": "指定月の月報と店舗表の両方にある店舗を取得し、店舗名順に表示する。", "explanation": "一致する店舗だけを取得するので、未提出の店舗が一覧から落ちる。"}, {"id": 3, "body": "店舗表を起点に全期間の月報を照合し、月報がなければ未提出とする。", "explanation": "別の月だけ提出した店舗を、指定月も提出したものとして扱ってしまう。"}, {"id": 4, "body": "店舗表を起点に指定月の月報を照合し、月報がなければ未提出とする。", "explanation": "全店舗を残したまま、指定月に限って月報の有無を判断できる。"}]'::jsonb, 4, '全店舗を母集団として残し、指定月の月報を店舗IDで照合する。対応する月報がなければ未提出と判定できる。', null, true),
  ('DMQ-0148', '検査項目と回答を同じ版にそろえる', '点検票は改訂のたびに版番号が変わり、項目番号は版ごとに振り直す。回答表は点検票の版番号と項目番号を保持する。例えば、第2版に項目3がなく、第1版に項目3がある場合でも、第2版の項目3への回答は登録できないようにしたい。項目の存在をデータベースの制約で保証する方法として、適切なものはどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "項目表の版番号と項目番号の組を一意にし、回答表からこの組を外部キーで参照する。", "explanation": "同じ行に版番号と項目番号がそろうことを要求できる。第1版に項目3があっても、第2版にないなら登録は拒否される。"}, {"id": 2, "body": "項目表の版番号と項目番号の組を一意にし、回答表の版番号と項目番号には必須制約を付ける。", "explanation": "空欄は防げるが、回答表に指定した項目が項目表に存在するかは検査しない。"}, {"id": 3, "body": "回答表の版番号は版一覧を、項目番号は全版共通の番号一覧を、それぞれ外部キーで参照する。", "explanation": "値が別々に存在することしか保証しない。版と項目の組が実在するかは確認できない。"}, {"id": 4, "body": "回答表の版番号と項目番号の組に索引を作り、版番号だけを外部キーで参照する。", "explanation": "索引で検索しやすくなり、版の存在も確認できるが、その版に項目が存在するかは確認しない。"}]'::jsonb, 1, '項目を特定するには版番号と項目番号の両方が必要である。項目表でこの組を一意にし、回答表から二つの値を組にして参照することで、指定した版に存在しない項目への回答を防げる。', null, true),
  ('DMQ-0149', 'データベースの体系的な構成', '音声資料を蓄積したデータベースについて、個々の音声の著作権とは別に、データベース自体が著作物として保護される根拠になり得るものはどれか。', 'DM-A-28-01-03', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "大量の音声を購入し、収集費用が高額であること。", "explanation": "投入費用の大きさだけでは、情報の選択や体系的な構成に創作性があるとはいえない。"}, {"id": 2, "body": "音声認識で文字を生成し、元の音声とともに保存していること。", "explanation": "自動処理による変換・保存だけでは、選択や体系的な構成の創作性は示せない。"}, {"id": 3, "body": "利用目的に合わせた資料の選択や分類体系に、作成者の創作性が表れていること。", "explanation": "情報の選択又は体系的な構成の創作性が、データベースの保護の根拠となる。"}, {"id": 4, "body": "各音声について、収録日時とファイルの長さを保存していること。", "explanation": "客観的な値を記録しているという事情だけでは、情報の選択や体系的な構成の創作性は示せない。"}]'::jsonb, 3, '著作権法では、情報の選択又は体系的な構成に創作性があるデータベースを著作物として保護する。個々の資料の権利は別途確認する。', null, true),
  ('DMQ-0150', '委託制作した図の著作権', '会社が外部の制作者に依頼し、創作性のある概念図の納品を受けた。契約は自社の製品説明資料への掲載を許諾するもので、著作権の譲渡について定めていない。会社は他社への利用許諾もできるように、図の著作権を取得したい。適切な対応はどれか。', 'DM-A-28-01-03', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "追加の制作費を支払い、支払記録を著作権取得の根拠とする。", "explanation": "追加の報酬を払うだけでは、著作権を譲渡する合意は成立しない。"}, {"id": 2, "body": "制作者と、譲渡を受ける権利の範囲を明示した契約を結ぶ。", "explanation": "対象となる権利を明示して譲渡の合意を得ることで、取得する範囲を明確にできる。"}, {"id": 3, "body": "元の契約に、製品説明資料への掲載期間を延長する条項を加える。", "explanation": "掲載期間の延長は利用許諾の変更であり、著作権の譲渡を意味しない。"}, {"id": 4, "body": "編集可能な元ファイルの納品を受け、会社名で管理台帳に登録する。", "explanation": "元ファイルを保有しても、ファイルに含まれる図の著作権が移転するわけではない。"}]'::jsonb, 2, '制作報酬と納品は、著作権の譲渡と別である。著作権を取得するには権利者と譲渡に合意し、対象の権利を契約で明らかにする。', null, true),
  ('DMQ-0151', '月次データを別の用途で使う', '製造会社は、有償で購入した設備稼働データを自社設備の保守計画に利用している。契約では保守計画への利用を認め、保守以外の用途に転用するには提供元の事前承諾が必要と定めている。営業部が同じデータで、稼働状況に応じた新サービスの価格を検討したい。利用前に取るべき対応はどれか。', 'DM-A-28-01-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "個別設備の番号を削除し、価格検討に必要な項目だけを利用する。", "explanation": "データ項目を減らしても、価格検討という利用目的は保守計画とは異なる。"}, {"id": 2, "body": "契約の担当部門に利用記録を残し、社内で権限を付けて利用する。", "explanation": "社内の承認やアクセス制御があっても、契約が求める提供元の事前承諾は得られない。"}, {"id": 3, "body": "価格検討用のコピーを保守用と分け、検討終了後に削除する。", "explanation": "コピーの分離や削除は管理上の措置であり、用途の追加を認める承諾の代わりにはならない。"}, {"id": 4, "body": "利用目的と担当部門を示し、提供元から事前に承諾を得る。", "explanation": "価格検討に使う前に、契約で求められた手続を満たすことができる。"}]'::jsonb, 4, '購入したデータの利用範囲は契約で定まる。この事例で認められた用途は自社の保守計画であり、新サービスの価格検討には、契約に従って事前承諾を得る必要がある。', null, true),
  ('DMQ-0152', '営業秘密の管理を取引先に広げる', '未公表で事業に有用な製造条件表を、製造委託先にも渡す。委託先の担当者が秘密として扱うべき範囲を認識でき、必要な担当者だけが利用できるようにする措置として、最も適切なものはどれか。', 'DM-A-28-01-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "秘密扱いの対象を書面で示し、委託先の必要な担当者に閲覧を限定する。", "explanation": "何を秘密として扱うかを担当者に伝え、業務に必要な範囲で共有できる。"}, {"id": 2, "body": "送信用ファイルを暗号化し、復号後は委託先の共有フォルダで管理する。", "explanation": "暗号化は送信時の保護に役立つが、受領後の秘密扱いの範囲と閲覧者が明確にならない。"}, {"id": 3, "body": "秘密扱いを自社の管理台帳に登録し、委託先では通常の業務資料として管理する。", "explanation": "自社だけで秘密扱いを記録しても、委託先の担当者には取扱いが伝わらない。"}, {"id": 4, "body": "利用期限と返却方法を指定し、委託先の登録済み利用者に閲覧を許可する。", "explanation": "期限と返却の取決めだけでは、秘密扱いの対象や閲覧を業務上必要な人に限定する方法が明確にならない。"}]'::jsonb, 1, '秘密管理性の判断では、情報を秘密として扱う意思が、情報に接する者に認識できることが重要である。対象の明示やアクセス制限を組み合わせると、委託先でも取扱いを具体化できる。', null, true),
  ('DMQ-0153', '委託先に渡すデータの再利用条件', '会社は取引データを分析会社に渡し、自社専用の需要予測モデルの開発を委託する。分析会社がデータを他の顧客向けの学習に転用することを防ぎ、契約終了後も委託先にデータが残らないようにしたい。契約と運用の組合せとして、最も適切なものはどれか。', 'DM-A-28-01-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "外部への開示を禁じ、原本は契約終了時に返却する。委託先内の処理方法は委託先に委ねる。", "explanation": "外部への開示禁止だけでは社内での転用を明確に禁じられず、原本の返却だけでは複製が残る可能性がある。"}, {"id": 2, "body": "委託業務への利用に限定し、納品後の再検証用として、分析会社に処理済みデータの保管を認める。", "explanation": "用途の制限は有効だが、終了後もデータを残さないという要件を満たさない。"}, {"id": 3, "body": "利用を委託業務に限定し、他社向けの学習への転用を禁じる。契約終了時は複製も消去し、その実施を確認する。", "explanation": "利用目的と禁止行為を明確にし、契約終了後に複製が残らないことまで確認できる。"}, {"id": 4, "body": "他社向けの学習には事前承諾を求め、納品物の確認後は、保管期間を委託先の規程に従わせる。", "explanation": "無断の転用を抑えられるが、終了時に確実に消去する条件は定まらない。"}]'::jsonb, 3, '秘密保持だけでは、委託先が内部で自らのために使う行為や契約終了後の取扱いが明確にならない。利用目的を限定し、他社向けへの転用の禁止と、複製を含む終了時の消去・確認まで定める。', null, true)
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0154', '分割入金のある注文の集計', '注文ごとに、請求額と入金済額を並べたい。注文明細表には商品明細ごとの金額が、入金表には入金1回ごとの金額がある。対象の注文には明細と入金がそれぞれ1件以上あり、同じ金額の明細や入金もある。両表に共通する項目は注文番号だけである。金額を正しく求められる方法はどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "注文番号で両表を結合し、注文別に明細金額と入金額をそれぞれ合計する。", "explanation": "明細が2件、入金が3件なら結合結果は6行になる。明細金額は各3回、入金額は各2回足される。"}, {"id": 2, "body": "両表を注文別にそれぞれ合計し、得られた二つの集計結果を注文番号で結合する。", "explanation": "結合する時点で両側とも1注文1行なので、明細も入金も1回ずつ合計に含まれる。"}, {"id": 3, "body": "注文番号で両表を結合し、注文別に明細金額と入金額の重複値を除いて合計する。", "explanation": "同額の入金が2回あった場合、そのうち1回が消える。金額が同じことと、同じ入金を重複して数えることは区別する必要がある。"}, {"id": 4, "body": "各表で注文内の行に連番を付け、注文番号と連番が一致する行を内部結合して合計する。", "explanation": "明細2件と入金3件なら、3回目の入金に対応する明細がなく、その入金が集計から落ちる。"}]'::jsonb, 2, '結合前に、各表を最終的に表示したい単位である「1注文1行」にそろえる。明細と入金は同じ注文に属していても、1件ずつ対応する関係ではない。', null, true),
  ('DMQ-0155', '地域別の売上を公表する条件', '小売店から売上データの提供を受けた。契約では、複数店舗の合計額を公表できるが、既に公表した額との組合せで1店舗の売上額が分かる公表は禁止している。対象は甲市1店、乙市3店、丙市4店で、全8店の今月の売上合計だけを公表済みである。次のうち、今月の集計値を一つだけ追加する場合、契約上、公表を見送るべきものはどれか。', 'DM-A-28-01-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "甲市と乙市の全4店の売上合計", "explanation": "全体から差し引いて分かるのは丙市4店の合計である。甲市の店の額は乙市3店の額と合算されている。"}, {"id": 2, "body": "丙市の全4店の売上合計", "explanation": "差し引いて得られるのは甲市と乙市を合わせた4店の合計である。"}, {"id": 3, "body": "甲市と丙市の全5店の売上合計", "explanation": "差し引いて得られるのは乙市3店の合計であり、1店の額には分解できない。"}, {"id": 4, "body": "乙市と丙市の全7店の売上合計", "explanation": "公表済みの8店合計からこの7店合計を引くと、残る甲市1店の売上額が求まる。"}]'::jsonb, 4, '公表する表に個店の欄がなくても、集計対象の差が1店なら、二つの合計額の差がその店の売上額になる。提供契約の条件は、公表済みの数値と組み合わせて判定する。', null, true),
  ('DMQ-0156', '生成画像と既存のポスターの類似性', '広告担当者が他社のポスターを生成AIに入力し、得られた画像を広告に使おうとしている。法務担当者は、元のポスターを参考にした経緯を確認した。次に、著作権法上の「類似性」を判断するため、両者のどの共通点を最も重視すべきか。', 'DM-A-28-01-05', 'ai_original', 'AI生成オリジナル（IPA非公式）。学習範囲の根拠：IPA DMシラバス案Ver.0.1。', '[{"id": 1, "body": "窓枠を五線譜に見立て、鳥と窓の留め金を一続きの旋律のように配した具体的な構図", "explanation": "題材の選び方だけでなく、複数の要素をどう組み合わせて見せたかという、作者固有の表現に関わる。"}, {"id": 2, "body": "駅で春の訪れを待つ人に、新生活への期待を感じてもらうという広告の着想", "explanation": "訴求したい気持ちや企画の着想が共通しても、それを絵でどう表したかは異なり得る。"}, {"id": 3, "body": "水彩絵の具のにじみを生かし、柔らかな色調で風景を描くという画風", "explanation": "技法や抽象的な画風の共通だけでは、特定のポスターの創作的表現が共通するとは判断できない。"}, {"id": 4, "body": "駅舎の竣工年と所在地を、市の公開資料どおりに記した案内文の内容", "explanation": "竣工年と所在地は事実である。事実が共通することと、記述や構図の創作的表現が共通することは別である。"}]'::jsonb, 1, '既存作品に基づいて作ったかという依拠性と、その作品の創作的表現が共通するかという類似性は、それぞれ検討する。この事例では、元作品を入力した経緯とは別に、要素の具体的な組合せに元作品の表現上の特徴が現れているかを比較する。', null, true)
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0157', '顧客満足度の集計', '小売会社が、全店舗の顧客を対象に実施したアンケートの結果を公表する。担当者の行為のうち、データの改ざんに該当するものはどれか。', 'DM-A-27-01-01', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/17kYnRxZQVQMvrIDe3XA7H-Lx9nWtIa-ON5HuOV_mlUQ/edit', '[{"id":1,"body":"回答数が目標に届かなかった店舗について、架空の顧客の回答を作り、実際に回収した回答として登録した。","explanation":"存在しない回答を作り、観測した事実として記録する行為は「ねつ造」に当たる。"},{"id":2,"body":"同じ回答がシステム障害で二重に登録されたことをログで確認し、修正履歴を残して重複分を集計から除いた。","explanation":"同じ回答が二重に記録された証拠がある。重複分を取り除けば、一人の回答を一回として集計できる。"},{"id":3,"body":"低評価を付けた顧客のコメントが好意的だったので、本人に確認せず、提出された評価値を高評価に書き換えて集計した。","explanation":"顧客が提出した値を担当者の解釈で変えており、「改ざん」に当たる。好意的なコメントと低い点数は両立し得るので、コメントだけで入力ミスとは判断できない。"},{"id":4,"body":"別の調査会社が公表した結果の考察を、自社の担当者が書いた考察として報告書に掲載した。","explanation":"他者の考察を自分の成果として示す行為は「盗用」に当たる。"}]'::jsonb, 3, '顧客が提出した値を担当者の解釈で変えており、「改ざん」に当たる。好意的なコメントと低い点数は両立し得るので、コメントだけで入力ミスとは判断できない。', null, true),
  ('DMQ-0158', '生成AIが示した統計', '担当者が生成AIに市場調査の要約を作らせたところ、「国内の中小企業の64％がサービスXを導入済み」とする文と、出典とされる報告書名が示された。この数値を顧客向け資料に掲載する前の確認として、最も適切なものはどれか。', 'DM-A-27-02-01', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/17kYnRxZQVQMvrIDe3XA7H-Lx9nWtIa-ON5HuOV_mlUQ/edit', '[{"id":1,"body":"報告書の発行元から原本を入手し、調査対象、設問及び集計表を確認して、その文が調査結果を正しく表しているかを確かめる。","explanation":"原本で「誰に」「何を尋ねたか」まで照合する。例えば、導入を検討した企業の64％が導入したとしても、国内の中小企業全体の導入率が64％とはいえない。"},{"id":2,"body":"発行元の刊行物一覧で報告書名と発行年が一致することを確かめ、生成AIが示した数値にその書誌情報を添える。","explanation":"報告書が実在しても、その数値が載っているとは限らない。生成AIは実在する資料名と誤った数値を結び付けることがある。これはハルシネーションの一例である。"},{"id":3,"body":"別の生成AIに同じ条件で質問し、同じ数値と報告書名が返ることを確かめ、二つの回答を照合結果として保存する。","explanation":"複数のAIが同じ誤情報に基づいて回答することがある。回答が一致しても、調査結果そのものを確認したことにはならない。"},{"id":4,"body":"発行元の集計表に「64％」という値があることを確かめ、どの回答を集計した値かは生成AIの説明に従う。","explanation":"同じ数値でも、「導入済み」と「導入予定」では意味が変わる。集計表の見出しと設問を読んで対応を確かめる必要がある。"}]'::jsonb, 1, '原本で「誰に」「何を尋ねたか」まで照合する。例えば、導入を検討した企業の64％が導入したとしても、国内の中小企業全体の導入率が64％とはいえない。', null, true),
  ('DMQ-0159', '問い合わせの自動振分け', 'ある会社のAIは、問い合わせを「優先対応」と「通常対応」に振り分ける。導入前の評価では全体の正解率が96％だったが、運用開始後、特定の言い回しを含む緊急の問い合わせが、しばしば「通常対応」と判定された。偏りを調べ、是正するための対応として、適切なものだけを全て挙げた組合せはどれか。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0160', '会員データの取扱い', '小売業者が、会員ごとの購買履歴を分析するため、氏名を会員コードに置き換えた。分析画面には氏名を表示しないが、同社は通常の業務で使う会員台帳とコードを容易に照合でき、個々の会員を識別できる。この購買履歴について、最も適切な説明はどれか。', 'DM-A-29-01-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1zMCnesVXU4GlgnAow-uuD_QD6J464rkTGvsCeyycWh0/edit', '[{"id":1,"body":"会員ごとに行を分けても、売れ筋の統計を作る目的で使う時点で、購買履歴全体が統計情報になる。","explanation":"分析に使う明細と、分析して得た統計結果は区別する。例えば「今月の購入者は300人」という集計結果を作っても、集計前の会員別明細には個人との対応が残る。"},{"id":2,"body":"氏名を会員コードに置き換えた時点で匿名加工情報になり、会員台帳との対応関係は判定に影響しない。","explanation":"匿名加工情報には、所定の基準に従って加工し、特定の個人を識別できず、元の個人情報を復元できないようにすることが求められる。この例ではコードから会員を特定できる。"},{"id":3,"body":"同社では容易な照合で本人が分かるので、この購買履歴は同社にとって個人情報に当たる。","explanation":"会員台帳をコードで検索すれば、誰の購買履歴か分かる。「氏名が表示されるか」だけでは判断できない。"},{"id":4,"body":"購買履歴と会員台帳を別のデータベースに保存すれば、台帳を検索できる場合でも個人情報に当たらない。","explanation":"データベースを分けることはアクセス管理に役立つが、この会社は通常業務で両者を容易に照合できる。保存場所を分けてもその事実は変わらない。"}]'::jsonb, 3, '判断のポイントは、当該事業者が通常の業務で容易に照合し、本人を識別できるかどうか。', null, true),
  ('DMQ-0161', '提携先への名簿の提供', '会員サービスを運営する会社が、自社で取得した会員の個人データを、国内の提携先が自社商品の販売に使えるように提供したい。個人情報保護法のオプトアウトによる第三者提供について、適切な記述だけを全て挙げた組合せはどれか。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0163', '返品時に参照する価格', 'ある小売会社では、同じ商品でも店舗や販売日によって価格が異なる。返品時には、当該取引で客が実際に支払った単価を確認したい。商品マスターには現在の標準単価を保持し、レシート番号と明細番号の組で販売明細を一意に特定できる。記録方法として最も適切なものはどれか。', 'DM-A-08-01-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/15gF3FUzPzD2OBPmKvTCRAyQj6AldfEu32zcqESYn0xE/edit', '[{"id":1,"body":"商品マスターに標準単価の変更履歴を残し、返品時には購入日に有効だった標準単価を使う。","explanation":"標準単価の履歴は、当時の基準価格を調べるには使える。しかし、その客に適用したクーポンなど、明細ごとの値引額までは分からない。"},{"id":2,"body":"販売明細に商品コードと値引き後の実売単価を記録し、返品時には該当する明細の単価を使う。","explanation":"商品コードは商品を特定し、販売明細はその取引の事実を記録する。値引き後の単価を明細に残せば、後日の価格改定後も元の取引で支払った単価を確認できる。"},{"id":3,"body":"店舗ごとの商品マスターに直近の実売単価を記録し、返品時には購入店舗における最新の値を使う。","explanation":"同じ店舗でも販売のたびに最新の値が変わる。後の客が別の価格で購入すると、元の客の単価を取り出せなくなる。"},{"id":4,"body":"店舗別・商品別に日々の売上金額と販売数量を保存し、返品時には購入日の平均単価を使う。","explanation":"例えば、同日に同じ商品を800円と1,000円で各1個販売すると平均は900円になる。これはどちらの客が支払った単価とも一致しない。"}]'::jsonb, 2, '判断の手掛かりは「当該取引で実際に支払った」という条件。商品に共通する基準値と、個々の取引で確定した値を区別する。', null, true),
  ('DMQ-0164', '店舗コードの品質評価', '本部が受け取った販売明細は200件である。店舗コードの品質指標を「全明細のうち、共通店舗マスターに登録されたコードが設定されている明細の割合」と定めた。検査結果は次のとおりで、各明細は一つの区分にだけ該当する。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0166', '支払データの更新', '支払予定表を更新した際、金額欄の数式を誤って上書きし、一部の支払額が変わった。閲覧者は権限をもつ担当者だけで、システムは通常どおり利用できた。この事象で直接損なわれた情報の性質はどれか。', 'DM-A-24-01-01', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1VsBKuIlokxC69YKcb3fR-dRgzgZ6Vd4Ge0XlIqHozFw/edit', '[{"id":1,"body":"機密性","explanation":"機密性は、情報を許可された者だけが利用できる性質である。権限のない者が閲覧した事実はない。"},{"id":2,"body":"可用性","explanation":"可用性は、必要なときに利用できる性質である。今回は予定表を開いて作業できている。"},{"id":3,"body":"完全性","explanation":"完全性は、情報の正確さや欠落のなさに関わる。故意の改ざんに加え、操作ミスによって金額が変わった場合にも損なわれる。"},{"id":4,"body":"追跡可能性","explanation":"追跡可能性は、誰が何をしたかを後からたどれることを指す。金額が誤っていても、操作履歴が残っていれば経緯は追跡できる。"}]'::jsonb, 3, '完全性は、情報の正確さや欠落のなさに関わる。故意の改ざんに加え、操作ミスによって金額が変わった場合にも損なわれる。', null, true),
  ('DMQ-0167', '公開予定の製品資料', '会社の規程では、発表前の製品価格は「関係者限り」、発表済みの製品仕様は「公開」とする。複数の区分が混在する資料には最も厳しい区分を適用する。広報担当者が、発表済みの仕様書の末尾に未発表の価格表を加えた。この時点での取扱いはどれか。', 'DM-A-24-03-01', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1VsBKuIlokxC69YKcb3fR-dRgzgZ6Vd4Ge0XlIqHozFw/edit', '[{"id":1,"body":"資料全体を「関係者限り」とし、価格表を含まない公開用の版を別に用意する。","explanation":"最も厳しい区分は未発表価格の「関係者限り」である。公開可能な情報だけを別の版にすれば、仕様を知らせる業務も進められる。"},{"id":2,"body":"仕様書のページ数が多いので、全体を「公開」として価格表に注意書きを付ける。","explanation":"ページ数の比率は規程の判定基準に含まれない。注意書きでは公開範囲を制限できない。"},{"id":3,"body":"価格表のページだけを目次から外し、全体を「公開」として取引先に配る。","explanation":"目次から消しても価格表はファイル内に残る。受領者はそのページを閲覧できる。"},{"id":4,"body":"価格の発表予定日を表紙に記載し、その日までは「公開」の区分で社内に保管する。","explanation":"将来の発表予定は現在の区分を変えない。発表前は保管中も規程に従う。"}]'::jsonb, 1, '最も厳しい区分は未発表価格の「関係者限り」である。公開可能な情報だけを別の版にすれば、仕様を知らせる業務も進められる。', null, true),
  ('DMQ-0168', '月末の応援要員', '月末の2日間だけ、応援担当者が東地区の未処理伝票を照合する。東地区の未処理伝票の閲覧だけで作業は完了する。権限は対象、操作、有効期間を個別に指定できる。最小権限の原則に最も合う設定はどれか。', 'DM-A-24-02-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1VsBKuIlokxC69YKcb3fR-dRgzgZ6Vd4Ge0XlIqHozFw/edit', '[{"id":1,"body":"全地区の未処理伝票を2日間だけ閲覧できる。","explanation":"期間と操作は適切だが、他地区の伝票まで見せる業務上の必要がない。"},{"id":2,"body":"東地区の未処理伝票を2日間だけ閲覧・訂正できる。","explanation":"対象と期間は適切だが、照合に訂正権限は要らない。"},{"id":3,"body":"東地区の未処理伝票を、次回の定期棚卸しまで閲覧できる。定期棚卸しは3か月後である。","explanation":"対象と操作は適切だが、作業後も権限が残る。今回は終了日をあらかじめ設定できる。"},{"id":4,"body":"東地区の未処理伝票を2日間だけ閲覧できる。","explanation":"対象を東地区の未処理分、操作を閲覧、期間を2日間に絞っており、三つの条件が業務に一致する。"}]'::jsonb, 4, '対象を東地区の未処理分、操作を閲覧、期間を2日間に絞っており、三つの条件が業務に一致する。', null, true),
  ('DMQ-0169', '異動後の売上明細', '経理から販売企画に異動した社員が、旧部署の明細をまだ閲覧できる。経理グループからは削除済みである。アクセス権一覧には、同じ明細への個人単位の許可が残っていた。新しい業務で明細は使わない。最も適切な対応はどれか。', 'DM-A-24-02-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1VsBKuIlokxC69YKcb3fR-dRgzgZ6Vd4Ge0XlIqHozFw/edit', '[{"id":1,"body":"経理グループからの削除日を台帳に記録し、権限見直しを完了する。","explanation":"グループ経由の権限を除いても、個人への直接付与は残る。台帳の記録だけでは閲覧を止められない。"},{"id":2,"body":"不要な個人単位の許可を取り消し、他の付与経路も含めて実際に閲覧できなくなったことを確認する。","explanation":"同じデータへの権限が複数の経路で付くことがある。不要な許可を外した後、最終的に有効な権限まで確かめる。"},{"id":3,"body":"パスワードを変更させ、個人単位の許可は次の異動に備えて保持する。","explanation":"パスワード変更は認証に関する措置である。同じ社員が再度ログインすれば、残っている許可で閲覧できる。"},{"id":4,"body":"個人単位の許可を残し、閲覧ログを毎週確認することで異動に伴う権限変更を完了する。","explanation":"ログ確認は不適切な利用を後で見つける手段である。業務上不要なアクセスを取り消す目的は達成できない。"}]'::jsonb, 2, '同じデータへの権限が複数の経路で付くことがある。不要な許可を外した後、最終的に有効な権限まで確かめる。', null, true),
  ('DMQ-0170', '共同分析の依頼', '取引先から、顧客明細を当日中に提供してほしいと依頼された。社内規程では、顧客明細の社外提供にはデータ管理責任者の事前承認が必要である。一方、社外提供を承認済みの月別集計表があり、取引先はその集計表でも目的を達成できる。適切な対応だけを全て挙げた組合せはどれか。
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0176', '販売データを取り込む順序', '本部は各店舗の販売明細を取り出し、項目名も単位も店舗の形式のまま分析基盤に格納する。その後、基盤内で列名をそろえ、金額を円単位に変換する。この一連の処理を表す用語はどれか。', 'DM-A-09-01-01', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"ETL","explanation":"ETLでは抽出（E）、変換（T）、格納（L）の順に進む。本問では単位を変換する前に格納している。"},{"id":2,"body":"ELT","explanation":"順序は抽出（Extract）→格納（Load）→変換（Transform）である。「元の形式のまま格納」が判断の手掛かりになる。"},{"id":3,"body":"データ仮想化","explanation":"データ仮想化は、分散したデータに統一的にアクセスできるようにする仕組みである。設問は明細を物理的に取り込む順序を問うている。"},{"id":4,"body":"アノテーション","explanation":"アノテーションは、画像や文章などに分類名や注釈を付ける作業である。項目名や単位の統一とは目的が異なる。"}]'::jsonb, 2, '順序は抽出（Extract）→格納（Load）→変換（Transform）である。「元の形式のまま格納」が判断の手掛かりになる。', null, true),
  ('DMQ-0177', '仕入担当者向けの分析環境', '全社の販売・在庫・仕入データは、統一した形式でデータウェアハウスに蓄積済みである。仕入部門は、必要な項目だけを取り出し、仕入先別・週別に集計して、自部門専用の分析用データ集合を作ることにした。この集合に最も適した名称はどれか。', 'DM-A-09-01-01', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"データレイク","explanation":"データレイクは多様なデータを元の形式も含めて蓄える基盤である。ここで新しく作るのは仕入分析に絞った集合である。"},{"id":2,"body":"データカタログ","explanation":"データカタログは、どのデータがどこにあり、どんな意味をもつかを探すための目録である。週別の集計値そのものとは役割が違う。"},{"id":3,"body":"データマート","explanation":"対象部門と分析目的に合わせて選択・集計したデータ集合はデータマートに当たる。全社の保管先と仕入担当者の利用範囲を区別する。"},{"id":4,"body":"トランザクションログ","explanation":"トランザクションログは更新などの履歴を記録し、復旧などに使う。業務目的に合わせて作った集計とは異なる。"}]'::jsonb, 3, '対象部門と分析目的に合わせて選択・集計したデータ集合はデータマートに当たる。全社の保管先と仕入担当者の利用範囲を区別する。', null, true),
  ('DMQ-0178', 'パンとスープの購買', 'ある店の会計1,000件のうち、パンを含む会計は200件、スープを含む会計は100件、両方を含む会計は40件であった。「パンを買った会計はスープも含みやすいか」を調べるリフト値はどれか。ここで、リフト値は、パンを含む会計でのスープ購入率を、全会計でのスープ購入率で割った値とする。', 'DM-A-09-02-10', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"0.04","explanation":"40 ÷ 1,000 ＝ 0.04は、全会計のうち両方を含む割合である。"},{"id":2,"body":"0.20","explanation":"40 ÷ 200 ＝ 0.20は、パンを含む会計でのスープ購入率である。リフト値を求めるには全体の購入率でさらに割る。"},{"id":3,"body":"0.50","explanation":"0.10 ÷ 0.20 ＝ 0.50は、問題文で指定された分子と分母を逆にした値である。"},{"id":4,"body":"2.00","explanation":"全体のスープ購入率は100 ÷ 1,000 ＝ 0.10。リフト値は（40 ÷ 200）÷ 0.10 ＝ 2.00である。パンを含む会計では、全体の2倍の割合でスープを購入している。"}]'::jsonb, 4, '全体のスープ購入率は100 ÷ 1,000 ＝ 0.10。リフト値は（40 ÷ 200）÷ 0.10 ＝ 2.00である。パンを含む会計では、全体の2倍の割合でスープを購入している。', null, true),
  ('DMQ-0179', '広告の効果を読む', '海辺の店では、気温が高くなる予報の日ほど冷たい飲料の広告配信を増やしている。昨年のデータを見ると、広告配信が多い日ほど飲料が多く売れた。広告の効果を検討する際に、最も適切な説明はどれか。', 'DM-A-09-02-05', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"気温が広告配信と売上の両方に関係し得るので、気温の条件をそろえるなどして比較する。","explanation":"暑さは広告を増やす理由であると同時に、飲料の需要を高める要因にもなる。その影響が混ざった比較から広告の効果だけを読み取ることはできない。"},{"id":2,"body":"広告を配信したのは販売前なので、この相関から広告による増加分を特定できる。","explanation":"原因が結果より前に起きることは、因果関係を判断する条件の一つにすぎない。気温による違いは残る。"},{"id":3,"body":"観測日数を増やすと、暑い日に広告を増やす運用の影響は自動的に消える。","explanation":"同じ運用で日数だけを増やしても、広告の多い日に暑い日が偏る傾向は残り得る。"},{"id":4,"body":"気温と売上にも相関があれば、広告には効果がなかったと判断できる。","explanation":"気温の影響と広告の効果は両立する。気温との相関は、広告の効果がゼロであることを示さない。"}]'::jsonb, 1, '暑さは広告を増やす理由であると同時に、飲料の需要を高める要因にもなる。その影響が混ざった比較から広告の効果だけを読み取ることはできない。', null, true),
  ('DMQ-0180', '倉庫別の出荷時間', '四つの倉庫で各200件の出荷時間を計測した。倉庫ごとの中央値と中央50％のばらつきを一つの図で見比べたい。最も適した方法はどれか。', 'DM-A-09-02-08', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"倉庫ごとの出荷時間の合計を円グラフで示す。","explanation":"円グラフが示すのは合計に対する構成比であり、個々の出荷時間の分布は読み取れない。"},{"id":2,"body":"倉庫ごとの平均出荷時間を棒グラフで示す。","explanation":"平均が同じ倉庫でも、中央値やばらつきは異なり得る。平均だけでは要求された二つの情報がそろわない。"},{"id":3,"body":"倉庫ごとに同じ目盛で箱ひげ図を並べる。","explanation":"箱の両端が第1・第3四分位数、箱の中の線が中央値を示す。同一目盛なら、位置と箱の長さを倉庫間で比較できる。"},{"id":4,"body":"各倉庫の最大値と最小値だけを折れ線で結ぶ。","explanation":"両端の値だけでは、中央の観測値が集中しているのか広く散らばっているのかを区別できない。"}]'::jsonb, 3, '箱の両端が第1・第3四分位数、箱の中の線が中央値を示す。同一目盛なら、位置と箱の長さを倉庫間で比較できる。', null, true),
  ('DMQ-0181', '工房の生産計画', '製品Aは1個当たり組立2時間・包装1時間で利益3千円、製品Bは組立1時間・包装1時間で利益2千円である。1日の上限は組立16時間、包装10時間。製造した製品は全て売れる。次の計画のうち、両方の上限を守り、利益が最大となるものはどれか。', 'DM-A-09-03-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"Aを8個、Bを0個","explanation":"組立16時間、包装8時間で実行できる。利益は3×8＝24千円で、イの26千円を下回る。"},{"id":2,"body":"Aを6個、Bを4個","explanation":"組立は2×6＋4＝16時間、包装は6＋4＝10時間。利益は3×6＋2×4＝26千円となる。利益の数値（千円）は「組立時間＋包装時間」に等しいため、上限は16＋10＝26。この計画は上限に達する。"},{"id":3,"body":"Aを4個、Bを6個","explanation":"組立14時間、包装10時間で実行できる。利益は3×4＋2×6＝24千円である。"},{"id":4,"body":"Aを7個、Bを3個","explanation":"利益は3×7＋2×3＝27千円だが、組立に2×7＋3＝17時間を要し、上限を1時間超える。"}]'::jsonb, 2, '組立は2×6＋4＝16時間、包装は6＋4＝10時間。利益は3×6＋2×4＝26千円となる。利益の数値（千円）は「組立時間＋包装時間」に等しいため、上限は16＋10＝26。この計画は上限に達する。', null, true),
  ('DMQ-0182', '予測モデルに渡す項目', '機械の修理依頼を受け付けた時点で、作業に何分かかるかを予測したい。過去の完了案件には、受付時の情報と修理後の記録がそろっている。実運用で使える教師あり学習の設計はどれか。', 'DM-A-10-02-03', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"実際の作業時間を入力し、受付時に既に判明している機種名を予測する。","explanation":"入力と予測対象が逆である。依頼時には実作業時間は分からず、知りたい対象も機種名ではない。"},{"id":2,"body":"修理完了時に確定する交換部品数を入力し、実際の作業時間を予測する。","explanation":"過去の記録に載っていても、受付時に確定していない項目はその場の予測に使えない。評価の際にも受付時と同じ条件を再現する。"},{"id":3,"body":"機種と症状だけで案件をグループ分けし、グループ番号を予測時間（分）とする。","explanation":"グループ番号は識別用の値であり、分単位の時間ではない。番号だけから作業時間を推定する根拠はない。"},{"id":4,"body":"受付時に判明している機種と症状を入力し、過去の実作業時間を正解として学習する。","explanation":"既知の機種・症状と実作業時間の対応を過去の例から学ぶ。分単位の数値を予測するので、教師あり学習の回帰に当たる。"}]'::jsonb, 4, '既知の機種・症状と実作業時間の対応を過去の例から学ぶ。分単位の数値を予測するので、教師あり学習の回帰に当たる。', null, true),
  ('DMQ-0183', '店舗のタイプを見つける', 'チェーン店では、店舗ごとに時間帯別の売上割合や客単価を記録している。各店舗がどのタイプに属するかを示す記録はない。担当者は、購買傾向が似た店舗のまとまりを見つけたい。最も適した方法はどれか。', 'DM-A-10-02-03', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"店舗間の特徴の近さを用いてクラスタリングし、各グループの特徴を後から調べる。","explanation":"正解ラベルを与えず、観測した特徴の似ている店舗をまとめるという目的に合う。グループ名や実務上の意味は結果を見て考える。"},{"id":2,"body":"過去に付けた正解の店舗タイプを使って分類器を学習し、新店舗にそのラベルを付ける。","explanation":"既存の正解ラベルを再現する教師あり分類である。今回は分類名を事前に定めていない。"},{"id":3,"body":"来月の売上額を目的変数とする回帰モデルを学習し、予測売上額だけを一覧にする。","explanation":"回帰は将来の数値の予測に向く。売上予測額の一覧からは、時間帯別の構成などが似た店舗のまとまりは直接得られない。"},{"id":4,"body":"販促施策を選ぶたびに利益を報酬として与え、施策の選び方を学習する。","explanation":"これは強化学習の例であり、目的は報酬が大きい行動の選択である。既存店舗のグループ分けとは異なる。"}]'::jsonb, 1, 'クラスタリングでは、各店舗のタイプを示す正解ラベルがなくても、時間帯別の売上割合や客単価などの特徴が似ている店舗をまとめられる。例えば、あるグループに夕方の売上割合が高い店舗が集まっていれば、その傾向をグループの特徴として説明できる。', null, true),
  ('DMQ-0184', '規程集を使う社内窓口', '旅費規程は毎月改定される。社内の生成AIに、質問のたびに有効な版の該当条文を参照させ、回答に根拠を添えたい。モデルを再学習せずにこの要件を満たす構成はどれか。', 'DM-A-10-03-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"回答のランダム性を低くし、同じ質問には毎回似た文章を生成させる。","explanation":"出力の揺れを抑えても、改定内容をモデルに渡したことにはならない。"},{"id":2,"body":"過去の回答例を数件示し、条文番号を付ける書き方をモデルにまねさせる。","explanation":"回答例は書式を整えるのに役立つが、現在有効な条文に基づく回答であることは保証できない。"},{"id":3,"body":"有効な規程を検索し、該当条文と版情報を入力に含め、それを根拠に回答させる。","explanation":"検索で得た資料を生成時の文脈に加えるRAGに当たる。検索対象の版を管理し、示された根拠と回答の対応も確認できる。"},{"id":4,"body":"複数回生成した回答の中で最も多く現れた条文番号を採用する。","explanation":"同じ古い知識を基に何度も答えれば、古い条文番号が多数を占めることもある。多数決は現行規程との照合にならない。"}]'::jsonb, 3, '検索で得た資料を生成時の文脈に加えるRAGに当たる。検索対象の版を管理し、示された根拠と回答の対応も確認できる。', null, true),
  ('DMQ-0185', '発注を補助するAI', '発注エージェントに対し「10万円以下は自動発注可、10万円を超える注文は送信前に人が承認する」と決めた。承認がない高額注文を実行させない仕組みとして最も適切なものはどれか。', 'DM-A-10-04-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1fFGccVWAlSAYQTl0DtoJefCZPaAPflUHeu8fVqsyTtY/edit', '[{"id":1,"body":"エージェントに規程を毎日読み込ませ、承認状態を発注機能では確認せず全件送信する。","explanation":"規程を読ませることは判断の助けになるが、未承認注文の実行を発注時に止める仕組みがない。"},{"id":2,"body":"発注機能が金額と当該注文の承認状態を照合し、10万円を超える未承認の注文は送信を保留する。","explanation":"発注時のチェックがガードレールとして働き、高額注文では人が決定する。金額がちょうど10万円なら「以下」に該当する。"},{"id":3,"body":"10万円を超える注文は直ちに送信し、翌朝のレポートで承認担当者が確認する。","explanation":"事後確認では、既に送信済みの注文を事前に保留できない。"},{"id":4,"body":"発注理由の説明文が十分に詳しければ、10万円を超えても自動送信する。","explanation":"説明の詳しさと人による承認は別の条件である。文章の出来によって承認を代替することはできない。"}]'::jsonb, 2, '発注時のチェックがガードレールとして働き、高額注文では人が決定する。金額がちょうど10万円なら「以下」に該当する。', null, true)
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0186', '店舗の営業時間', '公式サイト、配送システム、店頭アプリで、同じ店舗の営業時間が食い違っている。各システムは応答速度のためにデータの複製を必要とする。SSOT（信頼できる唯一の情報源）の考え方に最も合う運用はどれか。', 'DM-A-08-01-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"各システムで独立して修正し、多数決で営業時間を決定する。","explanation":"同じ古い値が複数に残ることもある。多数決では正しい値の責任主体が決まらない。"},{"id":2,"body":"最も新しい更新日時が付いたシステムを、内容の承認状況に関係なく正とする。","explanation":"更新日時が新しくても未承認や誤入力の可能性がある。時刻だけでは正本を定義できない。"},{"id":3,"body":"承認済みの店舗台帳を正と定め、変更をそこで受け付け、各システムの複製に反映する。","explanation":"正とするデータと更新経路が一つに定まる。参照用の複製が複数あっても、正本と同期すれば運用できる。"},{"id":4,"body":"最初に全システムへ同じ営業時間を登録し、以後の更新は各部門に任せる。","explanation":"最初の一致しか保証されず、営業時間が変われば再び食い違い得る。"}]'::jsonb, 3, '正とするデータと更新経路が一つに定まる。参照用の複製が複数あっても、正本と同期すれば運用できる。', null, true),
  ('DMQ-0187', '試用期間中のアンケート', '商品改良用の自由記述には連絡先が書かれていることがある。社内規程では、利用終了時に原本と分析用コピーを廃棄し、個人を識別できない集計結果は継続保管できる。担当者用フォルダにも原本のコピーがある。利用終了時の対応として最も適切なものはどれか。', 'DM-A-08-02-01', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"原本と分析用コピーの所在を確認し、規程に従って廃棄したことを記録する。継続利用する集計結果は所定の条件を確認する。","explanation":"廃棄対象には複製も含まれる。継続保管できる条件を満たした集計結果だけを区別して扱える。"},{"id":2,"body":"集計結果が完成した時点で原本を削除し、担当者が作ったコピーはその担当者の判断に任せる。","explanation":"担当者用フォルダのコピーも規程の対象であり、原本だけの削除では完了しない。"},{"id":3,"body":"原本と全てのコピーを読取り専用に変更し、廃棄工程を完了する。","explanation":"読取り専用にしても内容は残り、閲覧できる。更新制限だけでは廃棄したことにならない。"},{"id":4,"body":"自由記述の列名を変更し、元の文章を残したまま集計結果として保存する。","explanation":"列名を変えても自由記述の中身は残る。個人を識別できない集計結果に変わったとはいえない。"}]'::jsonb, 1, '廃棄対象には複製も含まれる。継続保管できる条件を満たした集計結果だけを区別して扱える。', null, true),
  ('DMQ-0188', '本部と事業部の役割', '全社共通の商品コードや品質指標は本部と事業部が合意して定め、各事業部はその共通ルールの下で、自部門固有の属性の定義と日々の品質改善を担う。この方針に最も適した権限配分はどれか。', 'DM-A-08-03-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"固有属性の追加や日々の入力修正も全て本部が決め、各事業部に決定権を与えない。","explanation":"全てを本部が決める中央集権型に近く、現場に固有属性の決定を任せる条件と合わない。"},{"id":2,"body":"商品コードを含めて各事業部が独立に定義し、全社共通のルールは設けない。","explanation":"部門ごとの自律性はあるが、共通の商品コードで連携する基盤が失われる。"},{"id":3,"body":"問い合わせ窓口だけを本部に集約し、共通ルールの変更は各事業部が単独で決定する。","explanation":"窓口の一本化だけでは全社統制にならない。各部門が単独で共通ルールを変えられると、他部門に影響する。"},{"id":4,"body":"共通事項の決定手続と事業部が判断できる範囲を明文化し、部門横断の変更は共同で審議する。","explanation":"全社で統一する部分と部門に委ねる部分を両立する連邦型の考え方である。判断が衝突したときの調整先も明確になる。"}]'::jsonb, 4, '全社で統一する部分と部門に委ねる部分を両立する連邦型の考え方である。判断が衝突したときの調整先も明確になる。', null, true),
  ('DMQ-0189', '移行前の取引先データ', '旧システムから取引先データを移す。担当者は「どの列に、どのような問題がどれだけあるか」を把握してから補正ルールを決めたい。この段階で実施するデータプロファイリングに該当するものはどれか。', 'DM-A-08-04-02', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"住所が空欄の全行を、仕様を確認する前に削除する。","explanation":"行の削除はデータを変える処置である。空欄が許容される取引先まで失う可能性がある。"},{"id":2,"body":"各列の欠損率、異なる値の数、値の出現頻度や形式の分布を調べる。","explanation":"データを観察・集計して実態を把握する。例えば桁数別の件数を出せば、どの形式について原因調査が必要かを絞れる。"},{"id":3,"body":"会社名が似ている行を、取引先番号を確認せずに一つに統合する。","explanation":"これは名寄せ・統合の処置である。似た名前だけでまとめれば、別法人を同一視する危険がある。"},{"id":4,"body":"新システムの必須入力チェックを有効にし、移行元の状態は調べずに取込みを始める。","explanation":"必須チェックは今後の品質を守る仕組みだが、既存データの特徴や問題の規模は分からない。"}]'::jsonb, 2, 'データを観察・集計して実態を把握する。例えば桁数別の件数を出せば、どの形式について原因調査が必要かを絞れる。', null, true),
  ('DMQ-0190', 'レポートの鮮度を調べる', '用語集には「日次在庫は毎朝6時までに更新」とある。担当者が確かめたいのは、今日のレポートに昨夜分のデータが実際に取り込まれたかどうかである。最も直接的な確認材料はどれか。', 'DM-A-08-05-01', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"「在庫数」に予約済み商品を含めるかを示す業務上の定義","explanation":"何を数えるかは分かるが、今日の更新が実行された事実は示さない。"},{"id":2,"body":"在庫表の数量列の型と小数点以下の桁数","explanation":"列の構造を説明する技術的な情報であり、いつどのデータを取り込んだかは分からない。"},{"id":3,"body":"昨夜分の取込対象日、実際の処理完了時刻、処理結果及び反映件数の記録","explanation":"対象日と実行結果を併せて確認すれば、古い日付のデータを正常終了扱いで取り込んだ場合も区別できる。"},{"id":4,"body":"在庫表から日次レポートまでの設計上の加工経路","explanation":"データリネージは本来の流れや依存関係をたどるのに役立つ。今回知りたい特定日の実績には運用記録が必要である。"}]'::jsonb, 3, '対象日と実行結果を併せて確認すれば、古い日付のデータを正常終了扱いで取り込んだ場合も区別できる。', null, true),
  ('DMQ-0191', '売上の短期的な変化', '月曜から金曜までの日販個数は順に18、24、30、12、21であった。当日を含む直近3営業日の単純移動平均を使う。木曜日と金曜日の値の組合せはどれか。', 'DM-A-09-03-04', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"木曜24個、金曜22個","explanation":"24＝（18＋24＋30）÷3は水曜の値。22は木曜の値で、どちらも対象日が一日ずれている。"},{"id":2,"body":"木曜22個、金曜21個","explanation":"木曜は（24＋30＋12）÷3＝22。金曜は火曜の24を外し、金曜の21を加えるので（30＋12＋21）÷3＝21となる。"},{"id":3,"body":"木曜22個、金曜17個","explanation":"木曜の22は正しい。金曜の17は（18＋12＋21）÷3で得られるが、月曜の18は直近3営業日に含まれない。"},{"id":4,"body":"木曜21個、金曜21個","explanation":"金曜の21は正しい。木曜までの直近3日は火・水・木なので、木曜は21ではなく22になる。"}]'::jsonb, 2, '木曜は（24＋30＋12）÷3＝22。金曜は火曜の24を外し、金曜の21を加えるので（30＋12＋21）÷3＝21となる。', null, true),
  ('DMQ-0192', '返品理由の改善会議', '返品100件を、一件につき一つの主因に分類した。内訳はサイズ違い38件、色の印象違い27件、配送遅延18件、破損10件、その他7件である。件数の多い順に改善対象を選び、累計で全件の75％以上をカバーしたい。必要な最少の分類数はどれか。', 'DM-A-09-03-03', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"2分類","explanation":"上位2分類では38＋27＝65件、累積65％で目標に届かない。"},{"id":2,"body":"4分類","explanation":"上位4分類は93件で目標を超えるが、4分類目を加える前に達成している。"},{"id":3,"body":"5分類","explanation":"全5分類で100％になるが、設問が求めるのは75％以上に初めて届く分類数である。"},{"id":4,"body":"3分類","explanation":"上位3分類の合計は38＋27＋18＝83件。累積比率が65％から83％に上がる3分類目で初めて75％に達する。"}]'::jsonb, 4, '上位3分類の合計は38＋27＋18＝83件。累積比率が65％から83％に上がる3分類目で初めて75％に達する。', null, true),
  ('DMQ-0193', '待ち時間の報告', '窓口の待ち時間を7人分計測すると、短い順に3、4、4、5、6、7、41分だった。報告書には「観測値を人数で二分する中央の値」を載せる。この値と名称の組合せはどれか。', 'DM-A-09-02-04', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"5分・中央値","explanation":"（7＋1）÷2＝4番目が中央なので5分である。最後の41分がさらに長くなっても、他の値が同じなら中央値は変わらない。"},{"id":2,"body":"10分・平均値","explanation":"合計70分÷7人＝10分は平均値である。長く待った1人の影響を受け、中央の人の待ち時間とは一致しない。"},{"id":3,"body":"4分・最頻値","explanation":"4分は2回現れるので最頻値である。最も多く観測された値が順位の中央とは限らない。"},{"id":4,"body":"38分・範囲","explanation":"41－3＝38分は最大値と最小値の差であり、分布の広がりを表す。"}]'::jsonb, 1, '（7＋1）÷2＝4番目が中央なので5分である。最後の41分がさらに長くなっても、他の値が同じなら中央値は変わらない。', null, true),
  ('DMQ-0194', '会員アンケートの対象', '会員全体のサービス満足度を調べたい。試験的に、アプリを毎日使う会員だけに調査し、回答率は100％だった。アプリ利用頻度によって満足度が違う可能性がある。本調査の設計として最も適切なものはどれか。', 'DM-A-09-02-07', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"同じ対象者に2回答えてもらい、回答件数を2倍にする。","explanation":"同じ対象の回答を増やしても、利用頻度の低い人の意見は入らない。"},{"id":2,"body":"毎日使う会員の中だけで、回答者を無作為に選び直す。","explanation":"抽出元が毎日使う人に限られているので、その中で無作為にしても全会員は代表できない。"},{"id":3,"body":"全会員を対象とする名簿から利用頻度別に無作為抽出し、集計時は各層が全会員に占める比率を反映する。","explanation":"利用頻度の低い層や未利用者も抽出対象に含められる。集計時に全体の構成を反映すれば、人数の少ない層を多めに調査した場合にも対応できる。"},{"id":4,"body":"毎日使う会員の回答率が100％なので、その平均を全会員の満足度とする。","explanation":"100％は「依頼した人の中で」の回答率である。そもそも依頼しなかった層の偏りは解消しない。"}]'::jsonb, 3, '利用頻度の低い層や未利用者も抽出対象に含められる。集計時に全体の構成を反映すれば、人数の少ない層を多めに調査した場合にも対応できる。', null, true),
  ('DMQ-0195', '配送費を含む受注集計', '注文表は注文1件につき1行で、注文Aの配送費は500円、注文Bの配送費も500円である。明細表にはAの商品が3行、Bの商品が2行ある。商品別の分析用に両表を注文番号で結合した。2注文の配送費合計を正しく求められる方法はどれか。', 'DM-A-09-02-09', 'ai_original', 'オリジナル演習問題（IPA非公式）。出典：https://docs.google.com/document/d/1hxw_T3NXKM3KpDbbc6OEuN6o-gkBCqZn_CSy-H3OkYA/edit', '[{"id":1,"body":"結合後の全5行の配送費を合計する。","explanation":"Aの500円が3回、Bの500円が2回現れる。合計は2,500円となり、明細行数の分だけ同じ注文の配送費を重ねて数える。"},{"id":2,"body":"結合後、配送費の金額について重複を除いてから合計する。","explanation":"金額だけで重複を除くと500円が1件だけ残る。注文番号が違えば、同じ金額でも二つの費用である。"},{"id":3,"body":"結合後の全5行の配送費合計を、注文数の2で割る。","explanation":"2,500÷2＝1,250円になる。注文ごとに明細数が違うので、結合後の総額を注文数で割っても元の総額に戻らない。"},{"id":4,"body":"結合後、注文番号ごとに注文表由来の配送費を1件分だけ取り出し、その結果を合計する。","explanation":"配送費が決まる単位は注文である。Aから500円、Bから500円を1回ずつ取り出すと、正しい総額は1,000円になる。"}]'::jsonb, 4, '配送費が決まる単位は注文である。Aから500円、Bから500円を1回ずつ取り出すと、正しい総額は1,000円になる。', null, true)
insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0196', '新工場の業務整理', '新工場の立上げにあたり、製品、調達、生産、出荷という業務領域にどのデータが属し、領域間で何を共有するかを一枚にまとめたい。列名やファイル配置は次の段階で決める。最も目的に合う資料はどれか。', 'DM-A-17-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"各表の列定義書","explanation":"列の型や桁数は表を実装するための情報で、業務領域間の全体像を示す単位としては細かすぎる。"},{"id":2,"body":"サブジェクトエリアモデル","explanation":"業務上の主題ごとにデータを大きくまとめ、その関係を示すので、各領域の境界と共有範囲を話し合える。"},{"id":3,"body":"夜間処理の運転時刻表","explanation":"処理の開始時刻や順序は分かるが、製品や出荷といった主題の関係は読み取れない。"},{"id":4,"body":"ディスクの配置図","explanation":"保管装置とファイルの対応が中心で、業務上の意味による区分を表さない。"}]'::jsonb, 2, '業務上の主題ごとにデータを大きくまとめ、その関係を示すので、各領域の境界と共有範囲を話し合える。', null, true),
  ('DMQ-0197', '温室の観測記録', '温室の端末は気温を記録する。集約装置は記録を受け取って時間帯別平均を作り、監視画面はその平均を取得する。この説明をデータフローとして正しく表したものはどれか。矢印はデータを渡す向きを示す。', 'DM-A-17-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"端末 → 監視画面（気温の記録）→ 集約装置（平均）","explanation":"画面が生の記録を受けて平均を渡す経路は記述されていない。"},{"id":2,"body":"集約装置 → 端末（気温の記録）→ 監視画面（平均）","explanation":"気温の発生元は端末であり、集約装置から端末に記録を送る関係ではない。"},{"id":3,"body":"監視画面 → 集約装置（平均）→ 端末（気温の記録）","explanation":"画面からの取得要求と、取得するデータそのものが流れる向きを混同している。"},{"id":4,"body":"端末 → 集約装置（気温の記録）→ 監視画面（平均）","explanation":"端末で生じた記録が集約装置で平均に加工され、その値を画面が受け取る。"}]'::jsonb, 4, '端末で生じた記録が集約装置で平均に加工され、その値を画面が受け取る。', null, true),
  ('DMQ-0198', '商品名の訂正', '店舗の販売端末は商品一覧のコピーを持つ。商品名は本部の台帳を正とし、端末へは毎晩、変更分を配信する。月曜の昼、本部で一つの商品名を訂正した。この構造から判断できることはどれか。', 'DM-A-17-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"次の配信を取り込むまでは、店舗に旧名が表示され得る。","explanation":"本部で訂正した時刻と、端末のコピーに反映する時刻が異なる。"},{"id":2,"body":"本部の台帳を訂正した瞬間に全端末で新名が表示される。","explanation":"夜間配信の構造には、昼の変更を即時に伝える経路が示されていない。"},{"id":3,"body":"店舗に旧名が表示されたなら、本部の訂正は失敗している。","explanation":"端末は自身のコピーを表示するので、端末の値だけでは本部の更新結果を判定できない。"},{"id":4,"body":"本部の台帳の訂正には、全端末で先に商品名を編集する必要がある。","explanation":"更新の起点は本部であり、店舗での先行編集を必要とする構造ではない。"}]'::jsonb, 1, '本部で訂正した時刻と、端末のコピーに反映する時刻が異なる。', null, true),
  ('DMQ-0199', '工房の講習申込み', '工房が講習会の受付を電子化する。データベース製品を選ぶ前に、担当者と概念データモデルの内容を合意したい。この段階で最も優先して確認する事項はどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"申込番号に使用する整数型のバイト数","explanation":"型の格納サイズは実装時の判断であり、申込みが業務上何を意味するかを決めない。"},{"id":2,"body":"申込検索に使う索引の列順","explanation":"索引は検索の効率に関わる。まず、どの業務対象をどう結び付けるかを定める必要がある。"},{"id":3,"body":"同じ講習の別日程を、別の開催回として扱うか","explanation":"開催回と申込みが何を表し、どの単位で対応するかが決まるため、概念モデルの合意に必要である。"},{"id":4,"body":"申込表を格納するディスクの空き容量","explanation":"容量は保管設備の条件であり、講習と開催回との意味上の関係を決めない。"}]'::jsonb, 3, '開催回と申込みが何を表し、どの単位で対応するかが決まるため、概念モデルの合意に必要である。', null, true),
  ('DMQ-0200', '図書室の蔵書点検', '本には、同じ書名・版でも複数の現物がある。一冊ずつ異なる所蔵番号を貼り、破損状態を記録する。書名と版の情報は書誌番号で識別する。一冊だけが破損したとき、その一冊を正確に更新できる設計はどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"書誌番号ごとに破損状態を一つ記録する。","explanation":"同じ書誌番号を持つ複数の現物のうち、どれが破損したかを区別できない。"},{"id":2,"body":"所蔵番号ごとに書誌番号と破損状態を記録する。","explanation":"破損が起こる単位は一冊の現物である。所蔵番号で対象を特定し、書誌番号から共通の書誌情報も参照できる。"},{"id":3,"body":"書名ごとに破損した冊数だけを記録する。","explanation":"冊数が分かっても、点検や修理の対象とする一冊を指定できない。"},{"id":4,"body":"版ごとに最後に点検した一冊の状態を上書きする。","explanation":"以前に点検した現物の状態が失われ、他の現物の状態と区別できない。"}]'::jsonb, 2, '破損が起こる単位は一冊の現物である。所蔵番号で対象を特定し、書誌番号から共通の書誌情報も参照できる。', null, true),
  ('DMQ-0201', '展示室の利用枠', '一つの利用枠には、予約がまだないか、予約が一件だけある。一件の予約は必ず一つの利用枠に対して行う。UMLの関連で、利用枠一つから見た予約の多重度と、予約一件から見た利用枠の多重度を、この順で表したものはどれか。', 'DM-A-17-02-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"0..1 と 1","explanation":"未予約なら予約数は0、埋まれば1である。成立した予約の行き先は必ず一枠である。"},{"id":2,"body":"1 と 0..1","explanation":"未予約の枠を認めず、逆に枠のない予約を認めてしまう。"},{"id":3,"body":"0..* と 1","explanation":"一枠に二件以上の予約を許してしまい、一枠一件までという条件に合わない。"},{"id":4,"body":"1 と 1","explanation":"全ての枠に予約を必須とするので、受付開始直後の空き枠を表現できない。"}]'::jsonb, 1, '未予約なら予約数は0、埋まれば1である。成立した予約の行き先は必ず一枠である。', null, true),
  ('DMQ-0202', '演奏会の担当表', '一つの楽曲を複数の奏者が演奏し、一人の奏者も複数の楽曲に出演する。同じ奏者は一つの楽曲で一つのパートを担当する。ある演奏会について、担当パートをどの単位で記録するのが適切か。', 'DM-A-17-02-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"奏者ごと","explanation":"同じ奏者でも楽曲により担当パートが異なり得る。"},{"id":2,"body":"楽曲ごと","explanation":"一つの楽曲に複数の奏者が参加するため、一つの値では各人の担当を表せない。"},{"id":3,"body":"演奏会ごと","explanation":"演奏会全体で一つの値を持っても、楽曲も奏者も区別できない。"},{"id":4,"body":"楽曲と奏者の組合せごと","explanation":"パートを一つに定める条件は、その演奏会で楽曲と奏者の両方を指定することである。"}]'::jsonb, 4, 'パートを一つに定める条件は、その演奏会で楽曲と奏者の両方を指定することである。', null, true),
  ('DMQ-0203', '修理伝票の行番号', '修理伝票には工場ごとの伝票番号を付ける。工場が違えば同じ伝票番号を使うことがある。各伝票の作業行には1から順に行番号を付ける。全工場の作業行を常に一意に識別するために必要な最小の組合せはどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"伝票番号、行番号","explanation":"異なる工場の同番号の伝票では、同じ行番号が現れ得る。"},{"id":2,"body":"工場番号、行番号","explanation":"同じ工場でも、伝票が変われば行番号は1から始まる。"},{"id":3,"body":"工場番号、伝票番号、行番号","explanation":"前の二つで伝票が決まり、その中で行番号が作業行を決める。いずれかを省くと識別できない場合がある。"},{"id":4,"body":"工場番号、伝票番号","explanation":"伝票までは決まるが、その伝票にある複数の作業行を区別できない。"}]'::jsonb, 3, '前の二つで伝票が決まり、その中で行番号が作業行を決める。いずれかを省くと識別できない場合がある。', null, true),
  ('DMQ-0204', '保冷庫の点検記録', '保冷庫が8台ある。先月、3台は各2回、4台は各1回点検し、残る1台は点検しなかった。「点検記録」には点検1回につき1行を作り、対象の保冷庫1台を参照する。先月の点検記録の行数と、その記録が参照する異なる保冷庫の台数はどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"8行、8台","explanation":"8は設備台帳の台数である。点検しなかった一台に点検記録は作られない。"},{"id":2,"body":"10行、7台","explanation":"行数は3×2＋4×1＝10。点検を受けた異なる保冷庫は3＋4＝7台である。"},{"id":3,"body":"7行、10台","explanation":"7は点検を受けた台数、10は点検の回数であり、二つの単位を逆にしている。"},{"id":4,"body":"10行、8台","explanation":"行数は正しいが、未点検の一台は先月の点検記録から参照されない。"}]'::jsonb, 2, '行数は3×2＋4×1＝10。点検を受けた異なる保冷庫は3＋4＝7台である。', null, true),
  ('DMQ-0205', '展示作品の貸出履歴', '美術館で、一つの作品を時期を変えて同じ施設へ何度も貸し出す。貸出のたびに全館で一意の貸出番号を付ける。返却後も、どの施設にいつ貸したかを一件ずつ調べたい。要件を満たす論理モデルはどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"貸出番号をキーとする表に、作品番号、施設番号、貸出日、返却日を記録する。","explanation":"貸出という出来事に一行を割り当てる。同じ作品と施設でも、異なる貸出番号で複数回の記録を持てる。"},{"id":2,"body":"作品番号をキーとする作品表に、直近の施設番号と貸出日を上書きする。","explanation":"作品ごとの最新の行き先は分かるが、次の貸出時に過去の記録が失われる。"},{"id":3,"body":"施設番号をキーとする施設表に、直近の作品番号と返却日を上書きする。","explanation":"同じ施設が借りた別作品や過去の貸出を独立した記録として保持できない。"},{"id":4,"body":"作品番号と施設番号を組み合わせたキーの表に、貸出日を一つ記録する。","explanation":"同じ組合せの二回目の貸出を別の行として登録できず、反復する貸出を識別できない。"}]'::jsonb, 1, '貸出という出来事に一行を割り当てる。同じ作品と施設でも、異なる貸出番号で複数回の記録を持てる。', null, true)
